(73,'ER_NPS','Employer NPS','EMPLOYER_CONTRIBUTION','FORMULA',NULL,NULL,NULL,'IF(NPS_FIXED_AMOUNT > 0, NPS_FIXED_AMOUNT, GREATEST(ROUND(BASIC * NPS_PERCENT / 100, 2), NPS_MINIMUM))','NPS_APPLICABLE = 1 AND CTC1 > 0',NULL,NULL,60,0,1,1,0,0,0,1,1,NULL,'2026-11-13 07:16:17'),
(74,'EMP_EPF','Employer EPF','EMPLOYER_CONTRIBUTION','FORMULA',NULL,NULL,NULL,'ROUND(IF(PF_WAGE_CEILING > 0, LEAST(PF_WAGE, PF_WAGE_CEILING), PF_WAGE) * PF_PERCENT / 100, 2)','PF_APPLICABLE = 1',NULL,NULL,70,0,1,1,0,0,0,1,1,NULL,'2026-11-13 07:16:17'),
(75,'ER_ADMIN','EPF Admin Charges','EMPLOYER_CONTRIBUTION','FORMULA',NULL,NULL,NULL,'IF(PF_WAGE_CEILING > 0, LEAST(ROUND(PF_WAGE * PF_ADMIN_PERCENT / 100, 2), PF_ADMIN_MAX), ROUND(PF_WAGE * PF_ADMIN_PERCENT / 100, 2))','PF_APPLICABLE = 1',NULL,NULL,80,0,1,1,0,0,0,1,1,NULL,'2026-11-13 07:16:17'),
(76,'EMP_ESI','Employer ESI','EMPLOYER_CONTRIBUTION','FORMULA',NULL,NULL,NULL,'ROUND(ESI_WAGE * ESI_EMPLOYER_PERCENT / 100, 2)','ESI_APPLICABLE = 1 AND STD_ESI_WAGE <= ESI_WAGE_LIMIT',NULL,NULL,90,0,1,1,0,0,0,1,1,'Eligibility uses the contractual wage, so LOP never makes an employee ESI-eligible','2026-11-13 07:16:32'),
