CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `apply_job`(

    IN p_emp_name VARCHAR(150),

    IN p_email VARCHAR(150),

    IN p_mobile VARCHAR(15),

    IN p_resume_url TEXT

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- check duplicate application

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE email = p_email
    AND hr_status IN ('PENDING','SELECTED');

    IF v_count = 0 THEN

        -- insert candidate application


            application_source,

            emp_name,

            email,

            mobile,

            resume_url,

            hr_status,

            onboarding_status

        )
        VALUES (

            'CAREERS_PAGE',

            p_emp_name,

            p_email,

            p_mobile,

            p_resume_url,

            'PENDING',

            'NOT_STARTED'

        );

        -- success response

        SELECT
            'Y' AS status,
            p_email AS email,
            'job applied successfully' AS remarks;

    ELSE

        -- duplicate application

        SELECT
            'N' AS status,
            p_email AS email,
            'candidate already applied' AS remarks;

    END IF;

END
