CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `authenticate_user`(
    IN p_emp_id VARCHAR(20),
    IN p_password VARCHAR(255)
)
BEGIN
    DECLARE v_count INT;

    SELECT COUNT(*) INTO v_count
    FROM user_login_details
    WHERE emp_id = p_emp_id
      AND BINARY enc_pwd = p_password  -- Added BINARY for case-sensitive password check
      AND status = 'ACTIVE';

    IF v_count > 0 THEN

        UPDATE user_login_details
        SET last_login = NOW()
        WHERE emp_id = p_emp_id;

        SELECT 
            'Y' AS status,
            'success' AS remarks,
            ud.*,
            uld.user_category,
            uld.is_first_login

        FROM user_details ud
        JOIN user_login_details uld
            ON ud.emp_id = uld.emp_id

        WHERE ud.emp_id = p_emp_id;

    ELSE

        SELECT 
            'N' AS status,
            'incorrect userid/pwd' AS remarks;

    END IF;

END
;;
DELIMITER ;
