/*!50003 DROP PROCEDURE IF EXISTS `employee_attendance_punch` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `employee_attendance_punch`(
    IN p_emp_id VARCHAR(20),
    IN p_ip VARCHAR(45),
    IN p_action VARCHAR(10)
)
BEGIN

    DECLARE v_location_id BIGINT DEFAULT NULL;
    DECLARE v_attendance_id BIGINT DEFAULT NULL;
    DECLARE v_punch_in DATETIME DEFAULT NULL;
    DECLARE v_punch_out DATETIME DEFAULT NULL;
    DECLARE v_status VARCHAR(20) DEFAULT NULL;
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_current_time DATETIME;


    /* =========================================================
       INDIA TIME
       ========================================================= */

    SET time_zone = '+05:30';

    SET v_current_time = NOW();


    /* =========================================================
       1. CHECK ACTION
       ========================================================= */

    IF UPPER(p_action) NOT IN ('IN', 'OUT') THEN

        SELECT
            'N' AS status,
            'Invalid action. Use IN or OUT' AS remarks;


    ELSE


        /* =====================================================
           2. CHECK ACTIVE EMPLOYEE
           ===================================================== */

        SELECT COUNT(*)
        INTO v_count

        FROM user_details ud

        INNER JOIN user_login_details uld
            ON ud.emp_id = uld.emp_id

        WHERE ud.emp_id = p_emp_id
          AND uld.status = 'ACTIVE';


        IF v_count = 0 THEN

            SELECT
                'N' AS status,
                'Employee not found or inactive' AS remarks;


        ELSE


            /* =================================================
               3. GET TODAY ATTENDANCE
               ================================================= */

            SET v_attendance_id = NULL;
            SET v_punch_in = NULL;
            SET v_punch_out = NULL;
            SET v_status = NULL;

            SELECT
                id,
                punch_in,
                punch_out,
                status

            INTO
                v_attendance_id,
                v_punch_in,
                v_punch_out,
                v_status

            FROM attendance

            WHERE emp_id = p_emp_id
              AND attendance_date = CURDATE()

            LIMIT 1;


            /* =================================================
               4. ATTENDANCE RECORD NOT FOUND
               ================================================= */

            IF v_attendance_id IS NULL THEN

                SELECT
                    'N' AS status,
                    'Attendance record not generated for today'
                    AS remarks;


            /* =================================================
               5. HOLIDAY
               ================================================= */

            ELSEIF UPPER(v_status) = 'HOLIDAY' THEN

                SELECT
                    'N' AS status,
                    'Cannot punch attendance on holiday'
                    AS remarks;


            /* =================================================
               6. LEAVE
               ================================================= */

            ELSEIF UPPER(v_status) = 'LEAVE' THEN

                SELECT
                    'N' AS status,
                    'Employee is on leave today'
                    AS remarks;


            ELSE


                /* =================================================
                   7. LOCATION CHECK

                   WFH:
                     DO NOT CHECK IP

                   Normal working day:
                     CHECK PUBLIC IP
                   ================================================= */

                SET v_location_id = NULL;


                IF UPPER(v_status) = 'WFH' THEN

                    /*
                       WFH does not require office IP validation.

                       location_id remains NULL.
                    */

                    SET v_location_id = NULL;


                ELSE

                    /*
                       Normal office attendance requires
                       authorized public IP.
                    */

                    SELECT id
                    INTO v_location_id

                    FROM attendance_locations

                    WHERE public_ip = p_ip
                      AND is_active = TRUE

                    LIMIT 1;


                    IF v_location_id IS NULL THEN

                        SELECT
                            'N' AS status,
                            'Unauthorized attendance location'
                            AS remarks;

                    END IF;

                END IF;


                /* =================================================
                   8. CONTINUE ONLY IF LOCATION IS VALID

                   For WFH:
                       v_status = WFH
                       v_location_id = NULL

                   For office:
                       v_location_id must be valid
                   ================================================= */

                IF UPPER(v_status) = 'WFH'
                   OR v_location_id IS NOT NULL THEN


                    /* =================================================
                       9. PUNCH IN
                       ================================================= */

                    IF UPPER(p_action) = 'IN' THEN


                        /* Already punched in */

                        IF v_punch_in IS NOT NULL THEN

                            SELECT
                                'N' AS status,
                                'Already punched in'
                                AS remarks;


                        ELSE

                            /* =========================================
                               PUNCH IN

                               Office:
                                   location_id = office location

                               WFH:
                                   location_id = NULL

                               Biometric fields are untouched.
                               ========================================= */

                            UPDATE attendance

                            SET
                                punch_in = v_current_time,
                                punch_out = NULL,
                                location_id = v_location_id,
                                status = 'PRESENT'

                            WHERE id = v_attendance_id;


                            SELECT
                                'Y' AS status,
                                'Punch in successful' AS remarks,
                                p_emp_id AS emp_id,
                                CURDATE() AS attendance_date,
                                v_current_time AS punch_in,
                                NULL AS punch_out,
                                v_location_id AS location_id;

                        END IF;


                    /* =================================================
                       10. PUNCH OUT
                       ================================================= */

                    ELSEIF UPPER(p_action) = 'OUT' THEN


                        /* Must punch in first */

                        IF v_punch_in IS NULL THEN

                            SELECT
                                'N' AS status,
                                'Punch in required before punch out'
                                AS remarks;


                        /* Already actually punched out */

                        ELSEIF v_punch_out > v_punch_in THEN

                            SELECT
                                'N' AS status,
                                'Already punched out'
                                AS remarks;


                        ELSE

                            /* =========================================
                               PUNCH OUT

                               Only punch_out is updated.
                               ========================================= */

                            UPDATE attendance

                            SET
                                punch_out = v_current_time

                            WHERE id = v_attendance_id;


                            SELECT
                                'Y' AS status,
                                'Punch out successful' AS remarks,
                                p_emp_id AS emp_id,
                                CURDATE() AS attendance_date,
                                v_current_time AS punch_out;

                        END IF;

                    END IF;

                END IF;

            END IF;

        END IF;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `finalize_payroll_attendance_proc` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `finalize_payroll_attendance_proc`(
    IN p_emp_id VARCHAR(20),
    IN p_month INT,
    IN p_year INT
)
main_block: BEGIN

    DECLARE v_user_category VARCHAR(20);

    DECLARE v_total_records INT DEFAULT 0;
    DECLARE v_finalized_records INT DEFAULT 0;
    DECLARE v_duplicate_groups INT DEFAULT 0;

    DECLARE v_error_no INT DEFAULT 0;
    DECLARE v_error_message TEXT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN

        GET DIAGNOSTICS CONDITION 1
            v_error_no = MYSQL_ERRNO,
            v_error_message = MESSAGE_TEXT;

        ROLLBACK;

        SELECT
            'N' AS status,
            CONCAT(
                'Database error [',
                COALESCE(v_error_no, 0),
                ']: ',
                COALESCE(v_error_message, 'Unknown error')
            ) AS remarks;

    END;

    SET time_zone = '+05:30';

    /* 1. Validate requester */

    IF p_emp_id IS NULL OR TRIM(p_emp_id) = '' THEN

        SELECT
            'N' AS status,
            'Requester employee ID is required.' AS remarks;

        LEAVE main_block;

    END IF;

    /* 2. Validate month and year */

    IF p_month IS NULL
       OR p_month NOT BETWEEN 1 AND 12
       OR p_year IS NULL
       OR p_year NOT BETWEEN 1900 AND 9999 THEN

        SELECT
            'N' AS status,
            'Invalid month or year.' AS remarks;

        LEAVE main_block;

    END IF;

    /* 3. Validate active ADMIN, HR or SUPERADMIN */

    SET v_user_category = NULL;

    SELECT MAX(UPPER(TRIM(user_category)))
    INTO v_user_category
    FROM user_login_details
    WHERE emp_id = TRIM(p_emp_id)
      AND UPPER(TRIM(status)) = 'ACTIVE';

    IF v_user_category IS NULL
       OR v_user_category NOT IN ('ADMIN', 'HR', 'SUPERADMIN') THEN

        SELECT
            'N' AS status,
            'Unauthorized: only active ADMIN, HR, or SUPERADMIN can finalize attendance.'
                AS remarks;

        LEAVE main_block;

    END IF;

    /* 4. Check summary records */

    SELECT
        COUNT(*),
        COALESCE(SUM(is_finalized = 'Y'), 0)
    INTO
        v_total_records,
        v_finalized_records
    FROM payroll_attendance_summary
    WHERE payroll_month = p_month
      AND payroll_year = p_year;

    IF v_total_records = 0 THEN

        SELECT
            'N' AS status,
            'Attendance not generated. No payroll attendance summaries exist for this month and year.'
                AS remarks;

        LEAVE main_block;

    END IF;

    /* 5. Reject duplicate employee summaries */

    SELECT COUNT(*)
    INTO v_duplicate_groups
    FROM (
        SELECT emp_id
        FROM payroll_attendance_summary
        WHERE payroll_month = p_month
          AND payroll_year = p_year
        GROUP BY emp_id
        HAVING COUNT(*) > 1
    ) AS duplicate_employees;

    IF v_duplicate_groups > 0 THEN

        SELECT
            'N' AS status,
            CONCAT(
                'Finalization blocked. ',
                v_duplicate_groups,
                ' employee(s) have duplicate attendance summaries. ',
                'Resolve the duplicates before finalizing.'
            ) AS remarks;

        LEAVE main_block;

    END IF;

    /* 6. Check whether already finalized */

    IF v_finalized_records = v_total_records THEN

        SELECT
            'N' AS status,
            'Attendance is already finalized for the selected month and year.'
                AS remarks;

        LEAVE main_block;

    END IF;

    /* 7. Finalize summaries transactionally */

    START TRANSACTION;

    UPDATE payroll_attendance_summary
    SET
        is_finalized = 'Y',
        updated_at = NOW()
    WHERE payroll_month = p_month
      AND payroll_year = p_year
      AND (is_finalized IS NULL OR is_finalized <> 'Y');

    COMMIT;

    SELECT
        'Y' AS status,
        CONCAT(
            'Payroll attendance finalized successfully for ',
            LPAD(p_month, 2, '0'),
            '/',
            p_year,
            '. Total summary records: ',
            v_total_records,
            '.'
        ) AS remarks;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `generate_attendance` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `generate_attendance`(
    IN p_attendance_date DATE
)
BEGIN

    IF p_attendance_date IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Attendance date cannot be NULL';
    END IF;

        emp_id,
        attendance_date,
        punch_in,
        punch_out,
        biometric_punch_in,
        biometric_punch_out,
        location_id,
        status
    )
    SELECT DISTINCT
        ud.emp_id,
        p_attendance_date,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,

        CASE
            /* Priority 1: Holiday */
            WHEN EXISTS (
                SELECT 1
                FROM holiday_master hm
                WHERE hm.holiday_date = p_attendance_date
                  AND hm.status = 'A'
            )
            THEN 'HOLIDAY'

            /* Priority 2: Approved WFH */
            WHEN EXISTS (
                SELECT 1
                FROM leave_application la
                INNER JOIN leave_type lt
                    ON lt.leave_type_id = la.leave_type_id
                WHERE la.emp_id = ud.emp_id
                  AND p_attendance_date
                      BETWEEN la.from_date AND la.to_date
                  AND UPPER(la.status) = 'APPROVED'
                  AND lt.leave_code = 'WFH'
                  AND lt.status = 'A'
            )
            THEN 'WFH'

            /* Priority 3: Approved leave */
            WHEN EXISTS (
                SELECT 1
                FROM leave_application la
                INNER JOIN leave_type lt
                    ON lt.leave_type_id = la.leave_type_id
                WHERE la.emp_id = ud.emp_id
                  AND p_attendance_date
                      BETWEEN la.from_date AND la.to_date
                  AND UPPER(la.status) = 'APPROVED'
                  AND lt.leave_code <> 'WFH'
                  AND lt.status = 'A'
            )
            THEN 'LEAVE'

            /* Priority 4: No attendance */
            ELSE 'ABSENT'
        END

    FROM user_details ud
    WHERE ud.emp_id IS NOT NULL
      AND EXISTS (
          SELECT 1
          FROM user_login_details ul
          WHERE ul.emp_id = ud.emp_id
            AND UPPER(ul.status) = 'ACTIVE'
      );

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
