/*!50003 DROP PROCEDURE IF EXISTS `get_attendence_monthly_report` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_attendence_monthly_report`(
    IN p_emp_id VARCHAR(20),
    IN p_month INT,
    IN p_year INT,
    IN p_category VARCHAR(20)
)
BEGIN

    DECLARE v_target_date DATE;
    DECLARE v_period_start DATE;
    DECLARE v_period_end DATE;
    DECLARE v_calculation_end DATE;
    DECLARE v_today DATE;

    DECLARE v_is_authorized INT DEFAULT 0;

    DECLARE v_total_employees INT DEFAULT 0;
    DECLARE v_today_present INT DEFAULT 0;
    DECLARE v_today_leave INT DEFAULT 0;
    DECLARE v_today_wfh INT DEFAULT 0;
    DECLARE v_today_absent INT DEFAULT 0;

    SET time_zone = '+05:30';

    SET v_today = DATE(NOW());


    /* =========================================================
       1. VALIDATE MONTH AND YEAR
       ========================================================= */

    IF p_month < 1
       OR p_month > 12
       OR p_year < 2000
       OR p_year > 2100 THEN

        SELECT
            'N' AS status,
            'Invalid month or year parameter provided.' AS remarks;

    ELSE

        /* =====================================================
           2. CREATE TARGET DATE
           ===================================================== */

        SET v_target_date = STR_TO_DATE(
            CONCAT(
                p_year,
                '-',
                LPAD(p_month, 2, '0'),
                '-01'
            ),
            '%Y-%m-%d'
        );


        /* =====================================================
           3. AUTHORIZATION

           p_category is used ONLY for authorization.

           ADMIN = allowed
           Other categories = denied
           ===================================================== */

        IF UPPER(TRIM(p_category)) = 'ADMIN' THEN
            SET v_is_authorized = 1;
        END IF;


        /* =====================================================
           4. ACCESS DENIED
           ===================================================== */

        IF v_is_authorized = 0 THEN

            SELECT
                'N' AS status,
                'Access Denied: Only ADMIN can view monthly attendance.' AS remarks;

        ELSE


            /* =================================================
               5. ATTENDANCE PERIOD

               Example:

               September 2026
               Period = August 25, 2026
                        to
                        September 24, 2026
               ================================================= */

            SET v_period_start = DATE_SUB(
                v_target_date,
                INTERVAL 1 MONTH
            );

            SET v_period_start = STR_TO_DATE(
                CONCAT(
                    YEAR(v_period_start),
                    '-',
                    LPAD(MONTH(v_period_start), 2, '0'),
                    '-25'
                ),
                '%Y-%m-%d'
            );

            SET v_period_end = DATE_SUB(
                DATE_ADD(
                    v_period_start,
                    INTERVAL 1 MONTH
                ),
                INTERVAL 1 DAY
            );


            /* =================================================
               6. CALCULATION END DATE
               ================================================= */

            IF v_today < v_period_start THEN

                SET v_calculation_end = NULL;

            ELSEIF v_today > v_period_end THEN

                SET v_calculation_end = v_period_end;

            ELSE

                SET v_calculation_end = v_today;

            END IF;


            /* =================================================
               7. PERIOD NOT STARTED
               ================================================= */

            IF v_calculation_end IS NULL THEN

                SELECT
                    'Y' AS status,
                    'Attendance period has not started yet.' AS remarks,
                    p_month AS month,
                    p_year AS year,
                    p_category AS category,
                    v_period_start AS period_start,
                    v_period_end AS period_end,
                    NULL AS calculated_until;

            ELSE


                /* =================================================
                   8. TOTAL ACTIVE EMPLOYEES

                   IMPORTANT:
                   NO CATEGORY FILTER HERE.

                   ALL ACTIVE EMPLOYEES ARE INCLUDED.
                   ================================================= */

                SELECT COUNT(DISTINCT ud.emp_id)
                INTO v_total_employees
                FROM user_details ud

                INNER JOIN user_login_details uld
                    ON uld.emp_id = ud.emp_id

                WHERE uld.status = 'ACTIVE';


                /* =================================================
                   9. TODAY'S ATTENDANCE

                   IMPORTANT:
                   NO CATEGORY FILTER HERE.

                   Counts are for ALL ACTIVE EMPLOYEES.
                   ================================================= */

                SELECT
                    COALESCE(
                        SUM(
                            CASE
                                WHEN a.status = 'PRESENT'
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    ),

                    COALESCE(
                        SUM(
                            CASE
                                WHEN a.status = 'LEAVE'
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    ),

                    COALESCE(
                        SUM(
                            CASE
                                WHEN a.status = 'WFH'
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    )

                INTO
                    v_today_present,
                    v_today_leave,
                    v_today_wfh

                FROM user_details ud

                INNER JOIN user_login_details uld
                    ON uld.emp_id = ud.emp_id

                LEFT JOIN attendance a
                    ON a.emp_id = ud.emp_id
                    AND DATE(a.attendance_date) = v_today

                WHERE uld.status = 'ACTIVE';


                /* =================================================
                   10. TODAY'S ABSENT COUNT
                   ================================================= */

                IF EXISTS (
                    SELECT 1
                    FROM holiday_master
                    WHERE holiday_date = v_today
                      AND status = 'A'
                ) THEN

                    SET v_today_absent = 0;

                ELSE

                    SET v_today_absent = GREATEST(
                        v_total_employees
                        - v_today_present
                        - v_today_wfh
                        - v_today_leave,
                        0
                    );

                END IF;


                /* =================================================
                   11. CREATE DATE RANGE
                   ================================================= */

                WITH RECURSIVE date_range AS (

                    SELECT
                        v_period_start AS attendance_date

                    UNION ALL

                    SELECT
                        DATE_ADD(
                            attendance_date,
                            INTERVAL 1 DAY
                        )

                    FROM date_range

                    WHERE attendance_date < v_calculation_end

                ),


                /* =================================================
                   12. ALL ACTIVE EMPLOYEES

                   IMPORTANT:
                   NO CATEGORY FILTER.

                   This is the main change that gives you
                   ALL MEMBERS.
                   ================================================= */

                active_employees AS (

                    SELECT
                        ud.emp_id,
                        ud.emp_name,
                        ud.department

                    FROM user_details ud

                    INNER JOIN user_login_details uld
                        ON uld.emp_id = ud.emp_id

                    WHERE uld.status = 'ACTIVE'

                ),


                /* =================================================
                   13. EMPLOYEE + EVERY DATE
                   ================================================= */

                employee_days AS (

                    SELECT
                        ae.emp_id,
                        ae.emp_name,
                        ae.department,

                        dr.attendance_date,

                        att.punch_in,
                        att.punch_out,
                        att.status AS raw_status

                    FROM active_employees ae

                    CROSS JOIN date_range dr

                    LEFT JOIN attendance att
                        ON att.emp_id = ae.emp_id
                        AND DATE(att.attendance_date) = dr.attendance_date

                ),


                /* =================================================
                   14. FINAL DAILY STATUS
                   ================================================= */

                employee_daily AS (

                    SELECT
                        ed.*,

                        CASE

                            WHEN EXISTS (
                                SELECT 1
                                FROM holiday_master hm
                                WHERE hm.holiday_date = ed.attendance_date
                                  AND hm.status = 'A'
                            )
                            THEN 'HOLIDAY'

                            ELSE COALESCE(
                                ed.raw_status,
                                'ABSENT'
                            )

                        END AS final_status

                    FROM employee_days ed

                )


                /* =================================================
                   15. FINAL MONTHLY REPORT

                   ONE ROW PER EMPLOYEE
                   ================================================= */

                SELECT

                    'Y' AS status,

                    'Monthly attendance fetched successfully'
                        AS remarks,

                    v_target_date AS selected_date,

                    v_today_present AS today_present,

                    v_today_leave AS today_leave,

                    v_today_wfh AS today_wfh,

                    v_today_absent AS today_absent,

                    p_month AS month,

                    p_year AS year,

                    p_category AS category,

                    v_period_start AS period_start,

                    v_period_end AS period_end,

                    v_calculation_end AS calculated_until,

                    ed.emp_id,

                    ed.emp_name AS employee_name,

                    dep.department_name,


                    /* =========================================
                       TOTAL DAYS
                       ========================================= */

                    COUNT(*) AS total_days,


                    /* =========================================
                       PRESENT
                       ========================================= */

                    SUM(
                        CASE
                            WHEN ed.final_status IN ('PRESENT', 'LATE')
                            THEN 1
                            ELSE 0
                        END
                    ) AS total_present,


                    /* =========================================
                       ABSENT
                       ========================================= */

                    SUM(
                        CASE
                            WHEN ed.final_status = 'ABSENT'
                            THEN 1
                            ELSE 0
                        END
                    ) AS total_absent,


                    /* =========================================
                       WFH
                       ========================================= */

                    SUM(
                        CASE
                            WHEN ed.final_status = 'WFH'
                            THEN 1
                            ELSE 0
                        END
                    ) AS total_wfh,


                    /* =========================================
                       LEAVE
                       ========================================= */

                    SUM(
                        CASE
                            WHEN ed.final_status = 'LEAVE'
                            THEN 1
                            ELSE 0
                        END
                    ) AS total_leave,


                    /* =========================================
                       HOLIDAYS
                       ========================================= */

                    SUM(
                        CASE
                            WHEN ed.final_status = 'HOLIDAY'
                            THEN 1
                            ELSE 0
                        END
                    ) AS total_holidays,


                    /* =========================================
                       TOTAL WORKING HOURS
                       ========================================= */

                    SEC_TO_TIME(
                        SUM(
                            CASE

                                /* Completed punch */
                                WHEN ed.punch_in IS NOT NULL
                                 AND ed.punch_out IS NOT NULL
                                 AND ed.punch_in <> ed.punch_out

                                THEN TIMESTAMPDIFF(
                                    SECOND,
                                    ed.punch_in,
                                    ed.punch_out
                                )


                                /* Punch-in = punch-out today */
                                WHEN ed.punch_in IS NOT NULL
                                 AND ed.punch_out IS NOT NULL
                                 AND ed.punch_in = ed.punch_out
                                 AND ed.attendance_date = v_today

                                THEN TIMESTAMPDIFF(
                                    SECOND,
                                    ed.punch_in,
                                    NOW()
                                )


                                /* Punch-in only today */
                                WHEN ed.punch_in IS NOT NULL
                                 AND ed.punch_out IS NULL
                                 AND ed.attendance_date = v_today

                                THEN TIMESTAMPDIFF(
                                    SECOND,
                                    ed.punch_in,
                                    NOW()
                                )

                                ELSE 0

                            END
                        )
                    ) AS total_hours,


                    /* =========================================
                       DAILY ATTENDANCE JSON
                       ========================================= */

                    (
                        SELECT JSON_ARRAYAGG(

                            JSON_OBJECT(

                                'date',
                                DATE_FORMAT(
                                    x.attendance_date,
                                    '%Y-%m-%d'
                                ),

                                'day_name',
                                DAYNAME(
                                    x.attendance_date
                                ),

                                'status',
                                x.final_status,


                                /* -----------------------------
                                   PUNCH IN
                                   ----------------------------- */

                                'punch_in',

                                CASE

                                    WHEN x.punch_in IS NOT NULL

                                    THEN DATE_FORMAT(
                                        x.punch_in,
                                        '%Y-%m-%d %H:%i:%s'
                                    )

                                    ELSE NULL

                                END,


                                /* -----------------------------
                                   PUNCH OUT
                                   ----------------------------- */

                                'punch_out',

                                CASE

                                    WHEN x.punch_in IS NOT NULL
                                     AND x.punch_out IS NOT NULL
                                     AND x.punch_in = x.punch_out

                                    THEN NULL

                                    WHEN x.punch_out IS NOT NULL

                                    THEN DATE_FORMAT(
                                        x.punch_out,
                                        '%Y-%m-%d %H:%i:%s'
                                    )

                                    ELSE NULL

                                END,


                                /* -----------------------------
                                   TOTAL HOURS
                                   ----------------------------- */

                                'total_hours',

                                CASE

                                    /* Completed day */

                                    WHEN x.punch_in IS NOT NULL
                                     AND x.punch_out IS NOT NULL
                                     AND x.punch_in <> x.punch_out

                                    THEN TIME_FORMAT(
                                        SEC_TO_TIME(
                                            TIMESTAMPDIFF(
                                                SECOND,
                                                x.punch_in,
                                                x.punch_out
                                            )
                                        ),
                                        '%H:%i:%s'
                                    )


                                    /* Today with same punch in/out */

                                    WHEN x.punch_in IS NOT NULL
                                     AND x.punch_out IS NOT NULL
                                     AND x.punch_in = x.punch_out
                                     AND x.attendance_date = v_today

                                    THEN TIME_FORMAT(
                                        SEC_TO_TIME(
                                            TIMESTAMPDIFF(
                                                SECOND,
                                                x.punch_in,
                                                NOW()
                                            )
                                        ),
                                        '%H:%i:%s'
                                    )


                                    /* Today with punch-in only */

                                    WHEN x.punch_in IS NOT NULL
                                     AND x.punch_out IS NULL
                                     AND x.attendance_date = v_today

                                    THEN TIME_FORMAT(
                                        SEC_TO_TIME(
                                            TIMESTAMPDIFF(
                                                SECOND,
                                                x.punch_in,
                                                NOW()
                                            )
                                        ),
                                        '%H:%i:%s'
                                    )

                                    ELSE NULL

                                END

                            )

                        )

                        FROM employee_daily x

                        WHERE x.emp_id = ed.emp_id

                        ORDER BY x.attendance_date

                    ) AS attendance_data


                FROM employee_daily ed

                LEFT JOIN department_master dep
                    ON dep.department_id = ed.department

                AND dep.status = '1'


                /* =========================================
                   GROUP ONE ROW PER EMPLOYEE
                   ========================================= */

                GROUP BY
                    ed.emp_id,
                    ed.emp_name,
                    ed.department,
                    dep.department_name


                ORDER BY ed.emp_id ASC;


            END IF;

        END IF;

    END IF;

END
;;
DELIMITER ;
