/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_attendence_period_summary_details`(
    IN p_emp_id VARCHAR(20),
    IN p_month INT,
    IN p_year INT
)
BEGIN

    DECLARE v_period_start DATE;
    DECLARE v_period_end DATE;
    DECLARE v_calculation_end DATE;
    DECLARE v_today DATE;

    DECLARE v_employee_count INT DEFAULT 0;
    DECLARE v_total_working_days INT DEFAULT 0;


    /* =========================================================
       TIMEZONE
       ========================================================= */

    SET time_zone = '+05:30';

    SET v_today = CURDATE();


    /* =========================================================
       VALIDATE MONTH
       ========================================================= */

    IF p_month < 1 OR p_month > 12 THEN

        SELECT
            'N' AS status,
            'Invalid month. Month must be between 1 and 12'
                AS remarks;

    ELSE


        /* =====================================================
           PERIOD

           Example:
           p_month = 8
           p_year  = 2026

           25 July 2026 -> 24 August 2026
           ===================================================== */

        SET v_period_start =
            DATE_SUB(
                STR_TO_DATE(
                    CONCAT(p_year, '-', p_month, '-25'),
                    '%Y-%m-%d'
                ),
                INTERVAL 1 MONTH
            );


        SET v_period_end =
            STR_TO_DATE(
                CONCAT(p_year, '-', p_month, '-24'),
                '%Y-%m-%d'
            );


        /* =====================================================
           CALCULATION END
           ===================================================== */

        IF v_today < v_period_end THEN

            SET v_calculation_end = v_today;

        ELSE

            SET v_calculation_end = v_period_end;

        END IF;


        /* =====================================================
           TOTAL WORKING DAYS

           Calendar days - holidays
           ===================================================== */

        SELECT
            (
                DATEDIFF(
                    v_calculation_end,
                    v_period_start
                ) + 1
            )
            -
            COUNT(DISTINCT hm.holiday_date)

        INTO v_total_working_days

        FROM holiday_master hm

        WHERE hm.holiday_date
              BETWEEN v_period_start
              AND v_calculation_end

          AND hm.status = 'A';


        /* =====================================================
           CHECK TEAM MEMBERS

           Only employees reporting to p_emp_id
           ===================================================== */

        SELECT COUNT(*)
        INTO v_employee_count

        FROM user_details ud

        INNER JOIN user_login_details uld
            ON uld.emp_id = ud.emp_id

        WHERE ud.reporting = p_emp_id
          AND uld.status = 'ACTIVE';


        /* =====================================================
           NO EMPLOYEES
           ===================================================== */

        IF v_employee_count = 0 THEN

            SELECT
                'N' AS status,

                'There are no employees reporting to this employee'
                    AS remarks,

                p_emp_id AS reporting_to,

                v_period_start AS period_start,

                v_period_end AS period_end,

                v_calculation_end AS calculated_until;


        ELSE


            /* =================================================
               SUMMARY PER EMPLOYEE
               ================================================= */

            SELECT

                'Y' AS status,

                'Attendance period summary fetched successfully'
                    AS remarks,


                /* =============================================
                   EMPLOYEE
                   ============================================= */

                ud.emp_id
                    AS emp_id,

                ud.emp_name
                    AS employee_name,


                /* =============================================
                   TOTAL PRESENT

                   Only PRESENT status
                   ============================================= */

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'PRESENT'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_present,


                /* =============================================
                   TOTAL WFH
                   ============================================= */

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'WFH'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_wfh,


                /* =============================================
                   TOTAL LEAVES
                   ============================================= */

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'LEAVE'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_leaves,


                /* =============================================
                   MISSED PUNCH

                   punch_in = punch_out
                   ============================================= */

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.punch_in IS NOT NULL
                             AND a.punch_out IS NOT NULL
                             AND a.punch_in = a.punch_out
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS missed_punch,


                /* =============================================
                   TOTAL HOURS

                   Only valid punch pairs
                   ============================================= */

                COALESCE(

                    SEC_TO_TIME(
                        SUM(
                            CASE

                                WHEN a.punch_in IS NOT NULL
                                 AND a.punch_out IS NOT NULL
                                 AND a.punch_out > a.punch_in

                                THEN TIMESTAMPDIFF(
                                    SECOND,
                                    a.punch_in,
                                    a.punch_out
                                )

                                ELSE 0

                            END
                        )
                    ),

                    '00:00:00'

                ) AS total_hours,


                /* =============================================
                   TOTAL WORKING DAYS
                   ============================================= */

                v_total_working_days
                    AS total_working_days,


                /* =============================================
                   TOTAL ABSENTS

                   Working days
                   - Present
                   - WFH
                   - Leave

                   Missed punch is NOT subtracted because
                   missed punch is still an attendance day.
                   ============================================= */

                GREATEST(

                    v_total_working_days

                    - COALESCE(
                        SUM(
                            CASE
                                WHEN a.status IN ('PRESENT', 'WFH')
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    )

                    - COALESCE(
                        SUM(
                            CASE
                                WHEN a.status = 'LEAVE'
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    ),

                    0

                ) AS total_absents,


                /* =============================================
                   PERIOD INFORMATION
                   ============================================= */

                v_period_start
                    AS period_start,

                v_period_end
                    AS period_end,

                v_calculation_end
                    AS calculated_until


            FROM user_details ud

            INNER JOIN user_login_details uld
                ON uld.emp_id = ud.emp_id


            LEFT JOIN attendance a
                ON a.emp_id = ud.emp_id

               AND a.attendance_date
                   BETWEEN v_period_start
                   AND v_calculation_end


            WHERE ud.reporting = p_emp_id
              AND uld.status = 'ACTIVE'


            GROUP BY
                ud.emp_id,
                ud.emp_name


            ORDER BY
                ud.emp_id;


        END IF;

    END IF;

END
;;
DELIMITER ;
