ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_candidate_details_by_ref_id`(

    IN p_ref_id VARCHAR(20)

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- validate candidate

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE ref_id = p_ref_id;

    IF v_count > 0 THEN

        -- get candidate full details

        SELECT

            'Y' AS status,

            id,

            ref_id,

            candidate_type,

            application_source,

            resume_url,

            offer_letter_url,

            temp_password,

            offer_status,

            onboarding_status,

            hr_status,

            current_step,

            is_submitted,

            emp_name,

            email,

            mobile,

            dob,

            gender,

            marital_status,

            father_name,

            mother_name,

            current_address,

            perminent_address,

            bank_holder_name,

            bank_name,

            bank_branch,

            bank_account_no,

            ifsc,

            upi_id,

            bank_account_type,

            pan,

            aadhaar,

            uan,

            skills,

            qualification,

            department,

            designation,

            reporting,

            remarks,

            created_by,

            received_on,

            updated_on,

            documents,
            experience

        FROM candidate_details
        WHERE ref_id = p_ref_id;

    ELSE

        SELECT

            'N' AS status,

            p_ref_id AS ref_id,

            'candidate not found' AS remarks;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
