CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_candidate_list`(
    IN p_application_source VARCHAR(30),
    IN p_onboarding_status VARCHAR(30),
    IN p_offer_status VARCHAR(20),
    IN p_candidate_type VARCHAR(20) -- Using candidate_type for category
)
BEGIN
    SET time_zone = '+05:30';

    IF p_application_source = 'CAREERS' THEN

        -- candidates applied from careers page
        SELECT
            ref_id,
            candidate_type,
            application_source,
            emp_name,
            email,
            mobile,
            offer_status,
            onboarding_status,
            hr_status,
            current_step,
            is_submitted,
            received_on
        FROM candidate_details
        WHERE application_source = 'CAREERS'
          AND (p_onboarding_status = 'ALL' OR onboarding_status = p_onboarding_status)
          AND (p_offer_status = 'ALL' OR offer_status = p_offer_status)
          AND (p_candidate_type = 'ALL' OR candidate_type = p_candidate_type)
        ORDER BY id DESC;

    ELSEIF p_application_source = 'HR' THEN

        -- candidates created by hr
        SELECT
            ref_id,
            candidate_type,
            application_source,
            emp_name,
            email,
            mobile,
            offer_status,
            onboarding_status,
            hr_status,
            current_step,
            is_submitted,
            created_by,
            received_on
        FROM candidate_details
        WHERE application_source = 'HR'
          AND (p_onboarding_status = 'ALL' OR onboarding_status = p_onboarding_status)
          AND (p_offer_status = 'ALL' OR offer_status = p_offer_status)
          AND (p_candidate_type = 'ALL' OR candidate_type = p_candidate_type)
        ORDER BY id DESC;

    ELSE

        -- all application sources
        SELECT
            ref_id,
            candidate_type,
            application_source,
            emp_name,
            email,
            mobile,
            offer_status,
            onboarding_status,
            hr_status,
            current_step,
            is_submitted,
            created_by,
            received_on
        FROM candidate_details
        WHERE (p_application_source = 'ALL' OR application_source = p_application_source)
          AND (p_onboarding_status = 'ALL' OR onboarding_status = p_onboarding_status)
          AND (p_offer_status = 'ALL' OR offer_status = p_offer_status)
          AND (p_candidate_type = 'ALL' OR candidate_type = p_candidate_type)
        ORDER BY id DESC;

    END IF;

END
;;
DELIMITER ;
