CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_details_from_employee_sal_to_deduction_list`(
    in p_month varchar(45), 
    in p_year varchar(45)
)
begin
    -- Insert Income Tax (TDS)
    select 
        es.emp_id as staff_id,
        'Income Tax' as deduction_name,
        es.tds as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;

    -- Insert Professional Tax (PT)
    select 
        es.emp_id as staff_id,
        'Professional Tax' as deduction_name,
        es.pt as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;

    -- Insert EPF (PF Employer Contribution + Admin Charges + PF Employee Contribution)
    select 
        es.emp_id as staff_id,
        'EPF' as deduction_name,
        (es.pf_employer_contribution + es.admin_charges + es.pf_employee_contribution) as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;

    -- Insert ESI (ESI Employee Contribution + ESI Employer Contribution)
    select 
        es.emp_id as staff_id,
        'ESI' as deduction_name,
        (es.esi_employee_contribution + es.esi_employer_contribution) as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;

    -- Insert NPS
    select 
        es.emp_id as staff_id,
        'NPS' as deduction_name,
        es.`nps` as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;

    -- Insert Other Deductions
    select 
        es.emp_id as staff_id,
        'Other Deductions' as deduction_name,
        es.`advances/ other_deductions` as d_amount,
        es.month as month,
        es.year as year
    from employee_salary es
    where es.month = p_month and es.year = p_year;
end
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
