CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_user_details`(
    IN p_emp_id VARCHAR(20)
)
BEGIN
    DECLARE v_count INT;

    SELECT COUNT(*) INTO v_count
    FROM user_details
    WHERE emp_id = p_emp_id;

    IF v_count > 0 THEN

        SELECT 
            'Y' AS status,
            'success' AS remarks,
            ud.id,
            ud.emp_id,
            ud.ref_id,
            ud.emp_name,
            ud.email,
            ud.mobile,
            ud.dob,
            ud.gender,
            ud.marital_status,
            ud.father_name,
            ud.mother_name,
            ud.current_address,
            ud.perminent_address,
            
            -- Department details
            ud.department AS department_id,
            IFNULL(dm.department_name, '') AS department_name,
            
            -- Designation details (Added Designation Name)
            ud.designation AS designation_id,
            IFNULL(desg.designation_name, '') AS designation_name,
            
            -- Reporting Details
            ud.reporting AS reporting_id,
            IFNULL(mgr.emp_name, '') AS reporting,
            
            ud.joining_date,
            ud.skills,
            ud.qualification,
            ud.experience,
            ud.bank_holder_name,
            ud.bank_name,
            ud.bank_branch,
            ud.bank_account_no,
            ud.ifsc,
            ud.upi_id,
            ud.bank_account_type,
            ud.pan,
            ud.pf_account_no,
            ud.esic_no,
            ud.aadhaar,
            ud.uan,
            ud.documents,
            ud.received_on,
            ud.updated_on,
            ud.at_blooms,
            ud.profisional_details_status,
            
            
            -- Account settings
            uld.user_category

        FROM user_details ud
        LEFT JOIN user_login_details uld
            ON ud.emp_id = uld.emp_id
        LEFT JOIN department_master dm
            ON ud.department = dm.department_id
        LEFT JOIN designation_master desg              -- 👈 New join for Designation Name
            ON ud.designation = desg.designation_id
        LEFT JOIN user_details mgr                     -- Self-join to get manager details
            ON ud.reporting = mgr.emp_id     
        WHERE ud.emp_id = p_emp_id;

    ELSE

        SELECT 
            'N' AS status,
            'incorrect userid' AS remarks;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
