CREATE DEFINER=`hrmstest`@`%` PROCEDURE `get_user_details_hrms`(
    IN p_emp_id VARCHAR(20),
    IN p_user_category VARCHAR(20)
)
BEGIN

    /* Single employee */
    IF p_emp_id IS NOT NULL AND p_emp_id <> '' THEN

        SELECT
            'y' AS status,
            'record found' AS remarks,
            id,
            emp_id,
            user_category,
            is_first_login,
            last_login,
            password_change_date,
            status,
            received_on,
            updated_on
        FROM user_login_details
        WHERE emp_id = p_emp_id
        AND user_category = p_user_category;

    /* Multiple employees by category */
    ELSE

        SELECT
            'y' AS status,
            'records found' AS remarks,
            id,
            emp_id,
            user_category,
            is_first_login,
            last_login,
            password_change_date,
            status,
            received_on,
            updated_on
        FROM user_login_details
        WHERE user_category = p_user_category
        ORDER BY emp_id;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
