CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `get_user_drop_down`(
    IN p_requestor_emp_id VARCHAR(20),  -- Requester checking permissions
    IN p_user_category VARCHAR(20)      -- Category filter for the dropdown list (Optional)
)
BEGIN

    DECLARE v_target_role VARCHAR(20) DEFAULT NULL;

    -- Set local time zone
    SET time_zone = '+05:30';

    -- 1. Verify if the requesting employee is an active HR or ADMIN
    IF p_requestor_emp_id IS NOT NULL AND p_requestor_emp_id != '' THEN
        SELECT user_category 
        INTO v_target_role
        FROM user_login_details
        WHERE emp_id = p_requestor_emp_id
          AND status = 'ACTIVE'
        LIMIT 1;
    END IF;

    -- 2. Reject if the requesting employee is not HR or ADMIN
    IF p_requestor_emp_id IS NULL OR p_requestor_emp_id = '' OR v_target_role NOT IN ('HR', 'ADMIN') THEN

        SELECT 
            'N' AS status,
            'Unauthorized: Only active HR or ADMIN can fetch the dropdown list' AS remarks,
            NULL AS emp_id,
            NULL AS emp_name,
            NULL AS user_category;

    ELSE

        -- 3. Success: Return ALL active employees for the dropdown
        SELECT 
            'Y' AS status,
            'Success' AS remarks,
            uld.emp_id,
            ud.emp_name,
            uld.user_category
        FROM user_login_details uld
        LEFT JOIN user_details ud 
            ON uld.emp_id = ud.emp_id
        WHERE 
            uld.status = 'ACTIVE'
        AND 
            (p_user_category IS NULL OR p_user_category = '' OR uld.user_category = p_user_category)
        ORDER BY 
            CASE 
                WHEN uld.user_category = 'ADMIN' THEN 1
                WHEN uld.user_category = 'HR' THEN 2
                ELSE 3
            END,
            ud.emp_name ASC;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
