CREATE DEFINER=`hrmstest`@`%` PROCEDURE `get_user_login_details_hrms`(
    IN p_emp_id VARCHAR(20),
    IN p_user_category VARCHAR(20)
)
BEGIN

    SELECT
        id,
        emp_id,
        user_category,
        is_first_login,
        last_login,
        password_change_date,
        status,
        received_on,
        updated_on
    FROM user_login_details
    WHERE
        (p_emp_id IS NULL OR p_emp_id = '' OR emp_id = p_emp_id)
    AND
        (p_user_category IS NULL OR p_user_category = '' OR user_category = p_user_category)
    ORDER BY user_category, emp_id;

END
;;
