/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_create_payroll_cycle_complete`(
    IN p_requester_emp_id VARCHAR(20),
    IN p_payroll_month TINYINT,
    IN p_payroll_year SMALLINT,
    IN p_payment_date DATE,
    IN p_period_start DATE,
    IN p_period_end DATE,
    IN p_remarks VARCHAR(500),
    IN p_cycle_code VARCHAR(50)
)
BEGIN
    /* ==========================================
       VARIABLE DECLARATIONS
       ========================================== */

    DECLARE v_requester_found INT DEFAULT 0;
    DECLARE v_employee_count INT DEFAULT 0;
    DECLARE v_attendance_count INT DEFAULT 0;
    DECLARE v_salary_count INT DEFAULT 0;
    DECLARE v_duplicate_count INT DEFAULT 0;

    DECLARE v_payroll_cycle_id BIGINT;
    DECLARE v_payroll_run_id BIGINT;

    DECLARE v_period_start DATE;
    DECLARE v_period_end DATE;

    DECLARE v_expected_start DATE;
    DECLARE v_expected_end DATE;

    DECLARE v_total_payroll_details INT DEFAULT 0;
    DECLARE v_total_components INT DEFAULT 0;
    DECLARE v_error_message VARCHAR(128) DEFAULT 'Payroll creation failed';
    DECLARE v_original_time_zone VARCHAR(64) DEFAULT '+00:00';
    DECLARE v_transaction_started TINYINT DEFAULT 0;

    /* Return status N and the SQL error in remarks for any failure. */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            v_error_message = MESSAGE_TEXT;

        IF v_transaction_started = 1 THEN
            ROLLBACK;
            SET v_transaction_started = 0;
        END IF;

        SET SESSION time_zone = v_original_time_zone;

        SELECT
            'N' AS status,
            COALESCE(v_error_message, 'Payroll creation failed') AS remarks,
            NULL AS payroll_cycle_id,
            TRIM(p_cycle_code) AS cycle_code,
            NULL AS payroll_run_id,
            p_payroll_month AS payroll_month,
            p_payroll_year AS payroll_year,
            p_period_start AS period_start,
            p_period_end AS period_end,
            p_payment_date AS payment_date,
            v_employee_count AS active_employee_count,
            v_total_payroll_details AS payroll_details_inserted,
            v_total_components AS payroll_components_inserted,
            'FAILED' AS payroll_run_status;
    END;


    /* Use Indian Standard Time during this procedure. */
    SET v_original_time_zone = @@SESSION.time_zone;
    SET SESSION time_zone = '+05:30';

    /* ==========================================
       STEP 1: VALIDATE INPUT PARAMETERS
       ========================================== */

    IF p_requester_emp_id IS NULL
       OR TRIM(p_requester_emp_id) = '' THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Requester employee ID is required';

    END IF;


    IF p_payroll_month IS NULL
       OR p_payroll_month NOT BETWEEN 1 AND 12 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Invalid payroll month';

    END IF;


    IF p_payroll_year IS NULL
       OR p_payroll_year < 2000
       OR p_payroll_year > 2100 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Invalid payroll year';

    END IF;


    IF p_cycle_code IS NULL
       OR TRIM(p_cycle_code) = '' THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll cycle code is required';

    END IF;


    IF p_period_start IS NULL
       OR p_period_end IS NULL THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll period start and end dates are required';

    END IF;


    IF p_period_start > p_period_end THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll start date cannot be after end date';

    END IF;


    /* ==========================================
       STEP 2: VALIDATE REQUESTER

       Only ACTIVE ADMIN or HR can create payroll.
       ========================================== */

    SELECT COUNT(*)
    INTO v_requester_found
    FROM user_login_details
    WHERE emp_id = p_requester_emp_id
      AND status = 'ACTIVE'
      AND user_category IN ('ADMIN', 'HR');


    IF v_requester_found = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Access denied: Active ADMIN or HR account required';

    END IF;


    /* ==========================================
       STEP 3: CALCULATE EXPECTED PAYROLL PERIOD

       Example:
       September 2026:
       Start = 2026-08-25
       End   = 2026-09-24
       ========================================== */

    SET v_expected_start = DATE_SUB(
        STR_TO_DATE(
            CONCAT(
                p_payroll_year,
                '-',
                LPAD(p_payroll_month, 2, '0'),
                '-25'
            ),
            '%Y-%m-%d'
        ),
        INTERVAL 1 MONTH
    );


    SET v_expected_end = STR_TO_DATE(
        CONCAT(
            p_payroll_year,
            '-',
            LPAD(p_payroll_month, 2, '0'),
            '-24'
        ),
        '%Y-%m-%d'
    );


    IF p_period_start <> v_expected_start
       OR p_period_end <> v_expected_end THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Invalid payroll period: dates must follow the 25th-to-24th cycle';

    END IF;


    SET v_period_start = p_period_start;
    SET v_period_end = p_period_end;


    /* ==========================================
       STEP 4: PREVENT DUPLICATE PAYROLL CYCLE

       Check month/year and cycle code.
       ========================================== */

    SELECT COUNT(*)
    INTO v_duplicate_count
    FROM payroll_cycles
    WHERE payroll_month = p_payroll_month
      AND payroll_year = p_payroll_year;


    IF v_duplicate_count > 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll cycle already exists for this month and year';

    END IF;


    SELECT COUNT(*)
    INTO v_duplicate_count
    FROM payroll_cycles
    WHERE cycle_code = TRIM(p_cycle_code);


    IF v_duplicate_count > 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll cycle code already exists';

    END IF;


    /* ==========================================
       STEP 5: COUNT ACTIVE EMPLOYEES
       ========================================== */

    SELECT COUNT(DISTINCT emp_id)
    INTO v_employee_count
    FROM user_login_details
    WHERE status = 'ACTIVE'
      AND emp_id IS NOT NULL
      AND TRIM(emp_id) <> '';


    IF v_employee_count = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'No active employees found';

    END IF;


    /* ==========================================
       STEP 6: VALIDATE FINALIZED ATTENDANCE

       Every active employee must have finalized
       attendance for the selected payroll month.
       ========================================== */

    SELECT COUNT(DISTINCT u.emp_id)
    INTO v_attendance_count
    FROM user_login_details u
    WHERE u.status = 'ACTIVE'
      AND u.emp_id IS NOT NULL
      AND TRIM(u.emp_id) <> ''
      AND EXISTS (
          SELECT 1
          FROM payroll_attendance_summary a
          WHERE a.emp_id = u.emp_id
            AND a.payroll_month = p_payroll_month
            AND a.payroll_year = p_payroll_year
            AND a.is_finalized = 'Y'
      );


    IF v_attendance_count <> v_employee_count THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Cannot create payroll: Some active employees have missing or unfinalized attendance';

    END IF;


    /* ==========================================
       STEP 7: VALIDATE ACTIVE SALARY STRUCTURES

       The active salary structure must overlap
       the payroll period.
       ========================================== */

    SELECT COUNT(DISTINCT u.emp_id)
    INTO v_salary_count
    FROM user_login_details u
    WHERE u.status = 'ACTIVE'
      AND u.emp_id IS NOT NULL
      AND TRIM(u.emp_id) <> ''
      AND EXISTS (
          SELECT 1
          FROM salary_structure ss
          WHERE ss.emp_id = u.emp_id
            AND ss.structure_status = 'ACTIVE'
            AND ss.effective_from <= v_period_end
            AND (
                ss.effective_to IS NULL
                OR ss.effective_to >= v_period_start
            )
      );


    IF v_salary_count <> v_employee_count THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Cannot create payroll: Some active employees do not have an applicable active salary structure';

    END IF;


    /* ==========================================
       STEP 8: START TRANSACTION
       ========================================== */

    START TRANSACTION;
    SET v_transaction_started = 1;


    /* ==========================================
       STEP 9: CREATE PAYROLL CYCLE
       ========================================== */

        cycle_code,
        payroll_month,
        payroll_year,
        period_start,
        period_end,
        payment_date,
        cycle_status,
        created_by,
        remarks
    )
    VALUES (
        TRIM(p_cycle_code),
        p_payroll_month,
        p_payroll_year,
        v_period_start,
        v_period_end,
        p_payment_date,
        'OPEN',
        p_requester_emp_id,
        NULLIF(TRIM(p_remarks), '')
    );


    SET v_payroll_cycle_id = LAST_INSERT_ID();


    /* ==========================================
       STEP 10: CREATE PAYROLL RUN
       ========================================== */

        payroll_cycle_id,
        run_number,
        run_type,
        run_status,
        total_employees,
        created_by
    )
    VALUES (
        v_payroll_cycle_id,
        1,
        'REGULAR',
        'DRAFT',
        v_employee_count,
        p_requester_emp_id
    );


    SET v_payroll_run_id = LAST_INSERT_ID();


    /* ==========================================
       STEP 11: INSERT EMPLOYEE PAYROLL DETAILS

       ctc1 = monthly CTC * payable days / 30

       Initial salary totals are zero.
       They will be calculated after component
       snapshots have been inserted.
       ========================================== */

        payroll_run_id,
        emp_id,
        structure_id,
        monthly_ctc,
        annual_ctc,
        total_days,
        payable_days,
        paid_leave_days,
        unpaid_leave_days,
        absent_days,
        ctc1,
        gross_earnings,
        total_deductions,
        employer_contributions,
        net_pay,
        calculation_version,
        calculation_remarks,
        employee_payroll_status
    )
    SELECT
        v_payroll_run_id,
        u.emp_id,
        ss.structure_id,
        ss.monthly_ctc,
        ss.annual_ctc,
        a.total_days,
        a.paid_days,
        0,
        a.unpaid_days,
        a.absent_days,

        ROUND(
            ss.monthly_ctc
            * LEAST(GREATEST(a.paid_days, 0), 30)
            / 30,
            2
        ),

        0.00,
        0.00,
        0.00,
        0.00,

        1,

        CONCAT(
            'Payroll created using a fixed 30-day salary basis. ',
            'Payable days capped at 30. Attendance finalized for ',
            LPAD(p_payroll_month, 2, '0'),
            '/',
            p_payroll_year
        ),

        'CALCULATED'

    FROM (
        SELECT DISTINCT emp_id
        FROM user_login_details
        WHERE status = 'ACTIVE'
          AND emp_id IS NOT NULL
          AND TRIM(emp_id) <> ''
    ) u

    INNER JOIN payroll_attendance_summary a
        ON a.emp_id = u.emp_id
       AND a.payroll_month = p_payroll_month
       AND a.payroll_year = p_payroll_year
       AND a.is_finalized = 'Y'

    INNER JOIN salary_structure ss
        ON ss.emp_id = u.emp_id
       AND ss.structure_status = 'ACTIVE'
       AND ss.effective_from <= v_period_end
       AND (
            ss.effective_to IS NULL
            OR ss.effective_to >= v_period_start
       );


    SET v_total_payroll_details = ROW_COUNT();


    /* ==========================================
       STEP 12: INSERT PAYROLL COMPONENT SNAPSHOTS

       Amount = monthly component amount
                * payable days / 30

       Amounts are saved as payroll snapshots.
       ========================================== */

        payroll_detail_id,
        component_id,
        component_code,
        component_name,
        component_type,
        calculation_type,
        component_value,
        percentage_base,
        percentage_value,
        formula_expression,
        calculated_amount,
        is_taxable
    )
    SELECT
        epd.payroll_detail_id,
        scm.component_id,
        scm.component_code,
        scm.component_name,
        scm.component_type,

        COALESCE(
            ess.calculation_type,
            scm.calculation_type
        ),

        COALESCE(
            ess.component_value,
            0.00
        ),

        COALESCE(
            ess.percentage_base,
            scm.percentage_base,
            'NONE'
        ),

        COALESCE(
            scm.percentage_value,
            0.00
        ),

        ess.formula_expression,

        ROUND(
            COALESCE(ess.monthly_amount, 0.00)
            * LEAST(
                GREATEST(epd.payable_days, 0),
                30
            )
            / 30,
            2
        ),

        COALESCE(
            scm.is_taxable,
            1
        )

    FROM employee_payroll_details epd

    INNER JOIN salary_structure ss
        ON ss.structure_id = epd.structure_id

    INNER JOIN employee_salary_structure ess
        ON ess.structure_id = ss.structure_id

    INNER JOIN salary_component_master scm
        ON scm.component_id = ess.component_id
       AND scm.is_active = 1

    WHERE epd.payroll_run_id = v_payroll_run_id;


    SET v_total_components = ROW_COUNT();


    /* ==========================================
       STEP 13: CALCULATE EMPLOYEE PAYROLL TOTALS

       Gross earnings =
           sum of EARNING components

       Total deductions =
           sum of DEDUCTION components

       Employer contributions =
           sum of EMPLOYER_CONTRIBUTION components

       Net pay =
           gross earnings - total deductions
       ========================================== */

    UPDATE employee_payroll_details epd

    SET
        epd.gross_earnings = (
            SELECT COALESCE(
                ROUND(SUM(
                    CASE
                        WHEN epc.component_type = 'EARNING'
                        THEN epc.calculated_amount
                        ELSE 0
                    END
                ), 2),
                0.00
            )
            FROM employee_payroll_component_details epc
            WHERE epc.payroll_detail_id = epd.payroll_detail_id
        ),

        epd.total_deductions = (
            SELECT COALESCE(
                ROUND(SUM(
                    CASE
                        WHEN epc.component_type = 'DEDUCTION'
                        THEN epc.calculated_amount
                        ELSE 0
                    END
                ), 2),
                0.00
            )
            FROM employee_payroll_component_details epc
            WHERE epc.payroll_detail_id = epd.payroll_detail_id
        ),

        epd.employer_contributions = (
            SELECT COALESCE(
                ROUND(SUM(
                    CASE
                        WHEN epc.component_type = 'EMPLOYER_CONTRIBUTION'
                        THEN epc.calculated_amount
                        ELSE 0
                    END
                ), 2),
                0.00
            )
            FROM employee_payroll_component_details epc
            WHERE epc.payroll_detail_id = epd.payroll_detail_id
        ),

        epd.net_pay = ROUND(
            (
                SELECT COALESCE(
                    SUM(
                        CASE
                            WHEN epc.component_type = 'EARNING'
                            THEN epc.calculated_amount
                            ELSE 0
                        END
                    ),
                    0.00
                )
                FROM employee_payroll_component_details epc
                WHERE epc.payroll_detail_id = epd.payroll_detail_id
            )
            -
            (
                SELECT COALESCE(
                    SUM(
                        CASE
                            WHEN epc.component_type = 'DEDUCTION'
                            THEN epc.calculated_amount
                            ELSE 0
                        END
                    ),
                    0.00
                )
                FROM employee_payroll_component_details epc
                WHERE epc.payroll_detail_id = epd.payroll_detail_id
            ),
            2
        ),

        epd.employee_payroll_status = 'CALCULATED',

        epd.calculation_remarks = CONCAT(
            COALESCE(epd.calculation_remarks, ''),
            ' Gross earnings, deductions, employer contributions, ',
            'and net pay calculated from payroll component snapshots.'
        )

    WHERE epd.payroll_run_id = v_payroll_run_id;


    /* ==========================================
       STEP 14: UPDATE PAYROLL RUN TOTALS

       Update the aggregate totals for the run.
       ========================================== */

    UPDATE payroll_runs pr

    INNER JOIN (
        SELECT
            payroll_run_id,

            COUNT(*) AS total_employees,

            ROUND(
                SUM(gross_earnings),
                2
            ) AS total_earnings,

            ROUND(
                SUM(total_deductions),
                2
            ) AS total_deductions,

            ROUND(
                SUM(employer_contributions),
                2
            ) AS total_employer_contributions,

            ROUND(
                SUM(net_pay),
                2
            ) AS total_net_pay

        FROM employee_payroll_details

        WHERE payroll_run_id = v_payroll_run_id

        GROUP BY payroll_run_id
    ) totals
        ON totals.payroll_run_id = pr.payroll_run_id

    SET
        pr.total_employees = totals.total_employees,

        pr.total_earnings = totals.total_earnings,

        pr.total_deductions = totals.total_deductions,

        pr.total_employer_contributions =
            totals.total_employer_contributions,

        pr.total_net_pay = totals.total_net_pay,

        pr.run_status = 'CALCULATED'

    WHERE pr.payroll_run_id = v_payroll_run_id;


    /* ==========================================
       STEP 15: VERIFY EMPLOYEE DETAIL COUNT
       ========================================== */

    IF v_total_payroll_details <> v_employee_count THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Payroll detail count mismatch; transaction cancelled';

    END IF;


    /* ==========================================
       STEP 16: APPROVE PAYROLL DIRECTLY

       This organization uses one authorized ADMIN/HR
       to calculate and approve payroll in one operation.
       No separate submit-for-review or approval procedure
       is required.
       ========================================== */

    UPDATE employee_payroll_details
    SET employee_payroll_status = 'APPROVED'
    WHERE payroll_run_id = v_payroll_run_id;

    UPDATE payroll_runs
    SET run_status = 'APPROVED',
        calculated_by = TRIM(p_requester_emp_id),
        calculated_at = NOW(),
        approved_by = TRIM(p_requester_emp_id),
        approved_at = NOW()
    WHERE payroll_run_id = v_payroll_run_id;

    /* Payroll cycle remains OPEN until explicit FINALIZE action. */

    /* ==========================================
       STEP 17: COMMIT TRANSACTION
       ========================================== */

    COMMIT;
    SET v_transaction_started = 0;


    /* ==========================================
       STEP 17: RETURN RESULT
       ========================================== */

    SET SESSION time_zone = v_original_time_zone;

    SELECT
        'Y' AS status,
        'Payroll calculated and directly approved successfully' AS remarks,
        v_payroll_cycle_id AS payroll_cycle_id,
        TRIM(p_cycle_code) AS cycle_code,
        v_payroll_run_id AS payroll_run_id,
        p_payroll_month AS payroll_month,
        p_payroll_year AS payroll_year,
        v_period_start AS period_start,
        v_period_end AS period_end,
        p_payment_date AS payment_date,
        v_employee_count AS active_employee_count,
        v_total_payroll_details AS payroll_details_inserted,
        v_total_components AS payroll_components_inserted,
        'APPROVED' AS payroll_run_status;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_generate_employee_payslips` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_generate_employee_payslips`(
    IN p_requester_emp_id VARCHAR(20),
    IN p_payroll_month TINYINT,
    IN p_payroll_year SMALLINT
)
BEGIN
    DECLARE v_old_time_zone VARCHAR(64) DEFAULT NULL;
    DECLARE v_requester_count INT DEFAULT 0;
    DECLARE v_cycle_id BIGINT DEFAULT NULL;
    DECLARE v_cycle_count INT DEFAULT 0;
    DECLARE v_paid_count INT DEFAULT 0;
    DECLARE v_unpaid_count INT DEFAULT 0;
    DECLARE v_existing_count INT DEFAULT 0;
    DECLARE v_inserted_count INT DEFAULT 0;
    DECLARE v_error_message TEXT DEFAULT NULL;
    DECLARE v_transaction_started TINYINT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error_message = MESSAGE_TEXT;
        IF v_transaction_started = 1 THEN ROLLBACK; END IF;
        IF v_old_time_zone IS NOT NULL THEN
            SET SESSION time_zone = v_old_time_zone;
        END IF;
        SELECT 'N' AS status,
               COALESCE(v_error_message, 'Payslip generation failed') AS remarks,
               p_payroll_month AS payroll_month,
               p_payroll_year AS payroll_year,
               0 AS payslips_generated;
    END;

    SET v_old_time_zone = @@SESSION.time_zone;
    SET SESSION time_zone = '+05:30';

    IF p_requester_emp_id IS NULL OR TRIM(p_requester_emp_id) = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Requester employee ID is required';
    END IF;
    IF p_payroll_month IS NULL OR p_payroll_month NOT BETWEEN 1 AND 12 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid payroll month; enter a value from 1 to 12';
    END IF;
    IF p_payroll_year IS NULL OR p_payroll_year NOT BETWEEN 2000 AND 2100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid payroll year';
    END IF;

    SELECT COUNT(*) INTO v_requester_count
    FROM user_login_details
    WHERE emp_id = TRIM(p_requester_emp_id)
      AND status = 'ACTIVE'
      AND UPPER(user_category) IN ('ADMIN', 'HR');

    IF v_requester_count = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Access denied: only active ADMIN or HR users can generate payslips';
    END IF;

    SELECT COUNT(*), MAX(payroll_cycle_id)
      INTO v_cycle_count, v_cycle_id
    FROM payroll_cycles
    WHERE payroll_month = p_payroll_month
      AND payroll_year = p_payroll_year;

    IF v_cycle_count = 0 OR v_cycle_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No payroll cycle exists for the selected month and year';
    END IF;
    IF v_cycle_count > 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Multiple payroll cycles exist for this month and year; resolve duplicates first';
    END IF;

    SELECT COUNT(DISTINCT epd.emp_id) INTO v_paid_count
    FROM employee_payroll_details epd
    JOIN payroll_runs pr ON pr.payroll_run_id = epd.payroll_run_id
    JOIN user_login_details u ON u.emp_id = epd.emp_id AND u.status = 'ACTIVE'
    WHERE pr.payroll_cycle_id = v_cycle_id
      AND epd.payment_status = 'PAID'
      AND epd.payment_decision = 'RELEASE'
      AND epd.employee_payroll_status <> 'CANCELLED';

    IF v_paid_count = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No active employees have released and fully PAID payroll for the selected month and year';
    END IF;

    SELECT COUNT(DISTINCT epd.emp_id) INTO v_unpaid_count
    FROM employee_payroll_details epd
    JOIN payroll_runs pr ON pr.payroll_run_id = epd.payroll_run_id
    JOIN user_login_details u ON u.emp_id = epd.emp_id AND u.status = 'ACTIVE'
    WHERE pr.payroll_cycle_id = v_cycle_id
      AND (epd.payment_status <> 'PAID'
           OR epd.payment_decision <> 'RELEASE'
           OR epd.employee_payroll_status = 'CANCELLED');

    SELECT COUNT(*) INTO v_existing_count
    FROM employee_payslips es
    JOIN employee_payroll_details epd ON epd.payroll_detail_id = es.payroll_detail_id
    JOIN payroll_runs pr ON pr.payroll_run_id = epd.payroll_run_id
    WHERE pr.payroll_cycle_id = v_cycle_id
      AND epd.payment_status = 'PAID'
      AND epd.payment_decision = 'RELEASE'
      AND epd.employee_payroll_status <> 'CANCELLED';

    START TRANSACTION;
    SET v_transaction_started = 1;

        payroll_detail_id, payslip_number, payslip_status,
        file_path, generated_by, generated_at
    )
    SELECT
        epd.payroll_detail_id,
        CONCAT('PS-', p_payroll_year, '-', LPAD(p_payroll_month, 2, '0'),
               '-', REPLACE(TRIM(epd.emp_id), ' ', ''), '-', epd.payroll_detail_id),
        'GENERATED',
        NULL,
        TRIM(p_requester_emp_id),
        NOW()
    FROM employee_payroll_details epd
    JOIN payroll_runs pr ON pr.payroll_run_id = epd.payroll_run_id
    JOIN user_login_details u ON u.emp_id = epd.emp_id AND u.status = 'ACTIVE'
    WHERE pr.payroll_cycle_id = v_cycle_id
      AND epd.payment_status = 'PAID'
      AND epd.payment_decision = 'RELEASE'
      AND epd.employee_payroll_status <> 'CANCELLED'
      AND NOT EXISTS (
          SELECT 1 FROM employee_payslips existing
          WHERE existing.payroll_detail_id = epd.payroll_detail_id
      );

    SET v_inserted_count = ROW_COUNT();
    COMMIT;
    SET v_transaction_started = 0;
    SET SESSION time_zone = v_old_time_zone;

    SELECT
        'Y' AS status,
        CASE WHEN v_inserted_count > 0
             THEN 'Payslip records generated successfully for eligible paid employees'
             ELSE 'Payslip records already exist; no duplicate records were created'
        END AS remarks,
        p_payroll_month AS payroll_month,
        p_payroll_year AS payroll_year,
        v_paid_count AS active_paid_employee_count,
        v_unpaid_count AS active_unpaid_or_held_employee_count,
        v_existing_count AS existing_paid_payslip_count,
        v_inserted_count AS payslips_generated,
        'GENERATED' AS payslip_status;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_get_employee_salary_structure` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_get_employee_salary_structure`(
    IN p_requester_emp_id VARCHAR(20),
    IN p_target_emp_id VARCHAR(20)
)
BEGIN
    DECLARE v_user_category VARCHAR(50) DEFAULT NULL;
    DECLARE v_user_status VARCHAR(20) DEFAULT NULL;
    DECLARE v_user_found INT DEFAULT 0;
    DECLARE v_target_found INT DEFAULT 0;

    -- Validate requesting user
    SELECT COUNT(*)
    INTO v_user_found
    FROM user_login_details
    WHERE emp_id = p_requester_emp_id;

    IF v_user_found = 0 THEN

        SELECT 'N' AS status,
               'Requesting employee not found' AS remarks;

    ELSE

        SELECT user_category, status
        INTO v_user_category, v_user_status
        FROM user_login_details
        WHERE emp_id = p_requester_emp_id
        LIMIT 1;

        IF LOWER(COALESCE(v_user_status, '')) <> 'active' THEN

            SELECT 'N' AS status,
                   'Requesting employee account is inactive' AS remarks;

        ELSEIF UPPER(COALESCE(v_user_category, ''))
               NOT IN ('ADMIN', 'HR') THEN

            SELECT 'N' AS status,
                   'Access denied. Only ADMIN or HR can view salary details'
                   AS remarks;

        ELSE

            -- Specific employee requested
            IF NULLIF(TRIM(p_target_emp_id), '') IS NOT NULL THEN

                SELECT COUNT(*)
                INTO v_target_found
                FROM user_login_details
                WHERE emp_id = TRIM(p_target_emp_id)
                  AND LOWER(COALESCE(status, '')) = 'active';

                IF v_target_found = 0 THEN

                    SELECT 'N' AS status,
                           'Target employee not found or inactive'
                           AS remarks;

                ELSE

                    SELECT
                        'Y' AS status,
                        'Employee salary details retrieved successfully'
                            AS remarks,

                        ud.emp_id,
                        ud.emp_name,
                        ss.structure_id,
                        ss.monthly_ctc,
                        ss.annual_ctc,
                        ss.effective_from,
                        ss.effective_to,
                        ss.structure_status,

                        COUNT(ess.employee_component_id)
                            AS total_components,

                        COALESCE(SUM(
                            scm.component_type = 'EARNING'
                        ), 0) AS earnings_count,

                        COALESCE(SUM(
                            scm.component_type = 'DEDUCTION'
                        ), 0) AS deductions_count,

                        COALESCE(SUM(
                            scm.component_type = 'EMPLOYER_CONTRIBUTION'
                        ), 0) AS employer_contribution_count,

                        COALESCE(
                            JSON_ARRAYAGG(
                                JSON_OBJECT(
                                    'employee_component_id',
                                        ess.employee_component_id,
                                    'component_id',
                                        scm.component_id,
                                    'component_code',
                                        scm.component_code,
                                    'component_name',
                                        scm.component_name,
                                    'component_type',
                                        scm.component_type,
                                    'calculation_type',
                                        ess.calculation_type,
                                    'component_value',
                                        ess.component_value,
                                    'percentage_base',
                                        ess.percentage_base,
                                    'formula_expression',
                                        ess.formula_expression,
                                    'monthly_amount',
                                        ess.monthly_amount,
                                    'is_taxable',
                                        scm.is_taxable,
                                    'is_active',
                                        scm.is_active
                                )
                            ),
                            JSON_ARRAY()
                        ) AS salary_components

                    FROM user_details ud

                    INNER JOIN salary_structure ss
                        ON ss.emp_id = ud.emp_id

                    INNER JOIN employee_salary_structure ess
                        ON ess.structure_id = ss.structure_id

                    INNER JOIN salary_component_master scm
                        ON scm.component_id = ess.component_id
                       AND scm.is_active = 1

                    WHERE ud.emp_id = TRIM(p_target_emp_id)
                      AND ss.effective_from <= CURDATE()
                      AND (
                          ss.effective_to IS NULL
                          OR ss.effective_to >= CURDATE()
                      )
                      AND UPPER(COALESCE(ss.structure_status, ''))
                          = 'ACTIVE'

                    GROUP BY
                        ud.emp_id,
                        ud.emp_name,
                        ss.structure_id,
                        ss.monthly_ctc,
                        ss.annual_ctc,
                        ss.effective_from,
                        ss.effective_to,
                        ss.structure_status;

                END IF;

            ELSE

                -- All active employees, active components only
                SELECT
                    'Y' AS status,
                    'Active employee salary details retrieved successfully'
                        AS remarks,

                    ud.emp_id,
                    ud.emp_name,
                    ss.structure_id,
                    ss.monthly_ctc,
                    ss.annual_ctc,
                    ss.effective_from,
                    ss.effective_to,
                    ss.structure_status,

                    COUNT(ess.employee_component_id)
                        AS total_components,

                    COALESCE(SUM(
                        scm.component_type = 'EARNING'
                    ), 0) AS earnings_count,

                    COALESCE(SUM(
                        scm.component_type = 'DEDUCTION'
                    ), 0) AS deductions_count,

                    COALESCE(SUM(
                        scm.component_type = 'EMPLOYER_CONTRIBUTION'
                    ), 0) AS employer_contribution_count,

                    COALESCE(
                        JSON_ARRAYAGG(
                            JSON_OBJECT(
                                'employee_component_id',
                                    ess.employee_component_id,
                                'component_id',
                                    scm.component_id,
                                'component_code',
                                    scm.component_code,
                                'component_name',
                                    scm.component_name,
                                'component_type',
                                    scm.component_type,
                                'calculation_type',
                                    ess.calculation_type,
                                'component_value',
                                    ess.component_value,
                                'percentage_base',
                                    ess.percentage_base,
                                'formula_expression',
                                    ess.formula_expression,
                                'monthly_amount',
                                    ess.monthly_amount,
                                'is_taxable',
                                    scm.is_taxable,
                                'is_active',
                                    scm.is_active
                            )
                        ),
                        JSON_ARRAY()
                    ) AS salary_components

                FROM user_details ud

                INNER JOIN user_login_details ul
                    ON ul.emp_id = ud.emp_id

                INNER JOIN salary_structure ss
                    ON ss.emp_id = ud.emp_id

                INNER JOIN employee_salary_structure ess
                    ON ess.structure_id = ss.structure_id

                INNER JOIN salary_component_master scm
                    ON scm.component_id = ess.component_id
                   AND scm.is_active = 1

                WHERE LOWER(COALESCE(ul.status, '')) = 'active'
                  AND ss.effective_from <= CURDATE()
                  AND (
                      ss.effective_to IS NULL
                      OR ss.effective_to >= CURDATE()
                  )
                  AND UPPER(COALESCE(ss.structure_status, ''))
                      = 'ACTIVE'

                GROUP BY
                    ud.emp_id,
                    ud.emp_name,
                    ss.structure_id,
                    ss.monthly_ctc,
                    ss.annual_ctc,
                    ss.effective_from,
                    ss.effective_to,
                    ss.structure_status

                ORDER BY ud.emp_id;

            END IF;

        END IF;

    END IF;

END
;;
DELIMITER ;
