CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_get_payroll_cycles`(
    IN p_emp_id VARCHAR(20),
    IN p_year SMALLINT
)
BEGIN
    DECLARE v_requester_found INT DEFAULT 0;
    DECLARE v_remarks VARCHAR(500) DEFAULT NULL;
    DECLARE v_cycle_count INT DEFAULT 0;

    /* =========================================
       STEP 1: DECLARE ERROR HANDLER
       ========================================= */

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            v_remarks = MESSAGE_TEXT;

        SELECT
            'N' AS status,
            v_remarks AS remarks;
    END;

    /* =========================================
       STEP 2: SET TIME ZONE
       ========================================= */

    SET time_zone = '+05:30';

    /* =========================================
       STEP 3: VALIDATE INPUT
       ========================================= */

    IF p_emp_id IS NULL OR TRIM(p_emp_id) = '' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Employee ID is required';
    END IF;

    IF p_year IS NULL OR p_year < 2000 OR p_year > 2100 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid payroll year';
    END IF;

    /* =========================================
       STEP 4: VALIDATE ADMIN OR HR
       ========================================= */

    SELECT COUNT(*)
    INTO v_requester_found
    FROM user_login_details
    WHERE emp_id = p_emp_id
      AND status = 'ACTIVE'
      AND user_category IN ('ADMIN', 'HR');

    IF v_requester_found = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Access denied: Active ADMIN or HR account required';
    END IF;

    /* =========================================
       STEP 5: CHECK PAYROLL CYCLES
       ========================================= */

    SELECT COUNT(*)
    INTO v_cycle_count
    FROM payroll_cycles
    WHERE payroll_year = p_year;

    IF v_cycle_count = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'No payroll cycles found for the selected year';
    END IF;

    /* =========================================
       STEP 6: GET PAYROLL CYCLE SUMMARY
       ========================================= */

    SELECT
        'Y' AS status,
        'Payroll cycles retrieved successfully' AS remarks,

        pc.payroll_cycle_id,
        pc.payroll_month,

        MONTHNAME(
            STR_TO_DATE(
                CONCAT(
                    pc.payroll_year,
                    '-',
                    LPAD(pc.payroll_month, 2, '0'),
                    '-01'
                ),
                '%Y-%m-%d'
            )
        ) AS month_name,

        pc.payroll_year,
        pc.period_start,
        pc.period_end,
        pc.payment_date,
        pc.cycle_status,

        pr.payroll_run_id,
        pr.run_number,
        pr.run_type,
        pr.run_status,

        COALESCE(pr.total_employees, 0)
            AS total_employees,

        COUNT(DISTINCT epd.payroll_detail_id)
            AS payroll_records,

        COALESCE(SUM(epd.gross_earnings), 0)
            AS total_gross_earnings,

        COALESCE(SUM(epd.total_deductions), 0)
            AS total_deductions,

        COALESCE(SUM(epd.net_pay), 0)
            AS total_net_pay

    FROM payroll_cycles pc

    LEFT JOIN payroll_runs pr
        ON pr.payroll_cycle_id = pc.payroll_cycle_id

    LEFT JOIN employee_payroll_details epd
        ON epd.payroll_run_id = pr.payroll_run_id

    WHERE pc.payroll_year = p_year

    GROUP BY
        pc.payroll_cycle_id,
        pc.payroll_month,
        pc.payroll_year,
        pc.period_start,
        pc.period_end,
        pc.payment_date,
        pc.cycle_status,
        pr.payroll_run_id,
        pr.run_number,
        pr.run_type,
        pr.run_status,
        pr.total_employees

    ORDER BY
        pc.payroll_month DESC,
        pr.run_number DESC;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
