CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_get_requests`(
    IN p_actor_emp_id VARCHAR(20)
)
main_block:BEGIN
    DECLARE v_actor_category VARCHAR(20);

    SET time_zone = '+05:30';

    -- Fetch the actor's role category (e.g., HR, ADMIN, EMPLOYEE, MANAGER)
    SELECT user_category INTO v_actor_category
    FROM user_login_details
    WHERE emp_id = p_actor_emp_id AND status = 'ACTIVE';

    -- 1. HR or ADMIN View: View everything across the org, filtering out Cancelled tickets
    IF v_actor_category IN ('HR', 'ADMIN') THEN
        SELECT 
            request_id, emp_id, category, subject, description, 
            attachment_path, progress, status, reason, resolved_id, created_at
        FROM general_requests
        WHERE status <> 'CANCELLED'
        ORDER BY created_at DESC;
        LEAVE main_block;
        
    -- 2. Regular Employee View: View only their own requests (including Cancelled ones)
    ELSE
        SELECT 
            request_id, emp_id, category, subject, description, 
            attachment_path, progress, status, reason, resolved_id, created_at
        FROM general_requests
        WHERE emp_id = p_actor_emp_id
        ORDER BY created_at desc;
        LEAVE main_block;
    END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
