CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_manage_payroll_status`(
    IN p_requester_emp_id VARCHAR(20),
    IN p_payroll_month TINYINT,
    IN p_payroll_year SMALLINT,
    IN p_action VARCHAR(20)
)
main: BEGIN

    DECLARE v_old_time_zone VARCHAR(64) DEFAULT NULL;
    DECLARE v_requester_found INT DEFAULT 0;
    DECLARE v_cycle_found INT DEFAULT 0;
    DECLARE v_cycle_id BIGINT DEFAULT NULL;
    DECLARE v_run_count INT DEFAULT 0;
    DECLARE v_detail_count INT DEFAULT 0;
    DECLARE v_invalid_count INT DEFAULT 0;
    DECLARE v_cycle_status VARCHAR(30) DEFAULT NULL;
    DECLARE v_action VARCHAR(20) DEFAULT NULL;
    DECLARE v_updated_count INT DEFAULT 0;
    DECLARE v_remarks TEXT DEFAULT NULL;
    DECLARE v_transaction_started TINYINT DEFAULT 0;

    /* =====================================================
       1. ERROR HANDLER
       ===================================================== */

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN

        IF v_transaction_started = 1 THEN
            ROLLBACK;
            SET v_transaction_started = 0;
        END IF;

        GET DIAGNOSTICS CONDITION 1
            v_remarks = MESSAGE_TEXT;

        IF v_old_time_zone IS NOT NULL THEN
            SET SESSION time_zone = v_old_time_zone;
        END IF;

        SELECT
            'N' AS status,
            COALESCE(
                v_remarks,
                'Payroll status update failed'
            ) AS remarks;

    END;

    /* =====================================================
       2. SAVE TIME ZONE
       ===================================================== */

    SET v_old_time_zone = @@SESSION.time_zone;

    SET SESSION time_zone = '+05:30';

    /* =====================================================
       3. VALIDATE INPUTS
       ===================================================== */

    IF p_requester_emp_id IS NULL
       OR TRIM(p_requester_emp_id) = '' THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Requester employee ID is required';

    END IF;

    IF p_payroll_month IS NULL
       OR p_payroll_month NOT BETWEEN 1 AND 12 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Invalid payroll month';

    END IF;

    IF p_payroll_year IS NULL
       OR p_payroll_year NOT BETWEEN 2000 AND 2100 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Invalid payroll year';

    END IF;

    SET v_action = UPPER(TRIM(p_action));

    IF v_action IS NULL
       OR v_action NOT IN ('FINALIZE', 'PAID') THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Invalid action. Allowed actions: FINALIZE, PAID';

    END IF;

    /* =====================================================
       4. VALIDATE REQUESTER
       ===================================================== */

    SELECT COUNT(*)
    INTO v_requester_found
    FROM user_login_details
    WHERE emp_id = TRIM(p_requester_emp_id)
      AND UPPER(status) = 'ACTIVE'
      AND UPPER(user_category) IN ('ADMIN', 'HR');

    IF v_requester_found = 0 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Access denied: Active ADMIN or HR account required';

    END IF;

    /* =====================================================
       5. START TRANSACTION
       ===================================================== */

    START TRANSACTION;

    SET v_transaction_started = 1;

    /* =====================================================
       6. FIND PAYROLL CYCLE
       ===================================================== */

    SELECT
        COUNT(*),
        MAX(payroll_cycle_id)
    INTO
        v_cycle_found,
        v_cycle_id
    FROM payroll_cycles
    WHERE payroll_month = p_payroll_month
      AND payroll_year = p_payroll_year;

    IF v_cycle_found = 0 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Payroll cycle not found for the selected month and year';

    END IF;

    IF v_cycle_found > 1 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Multiple payroll cycles found for this month and year';

    END IF;

    /* Lock payroll cycle */
    SELECT cycle_status
    INTO v_cycle_status
    FROM payroll_cycles
    WHERE payroll_cycle_id = v_cycle_id
    FOR UPDATE;

    /* =====================================================
       7. VALIDATE PAYROLL DATA EXISTS
       ===================================================== */

    SELECT COUNT(*)
    INTO v_run_count
    FROM payroll_runs
    WHERE payroll_cycle_id = v_cycle_id;

    IF v_run_count = 0 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'No payroll run found for this cycle';

    END IF;

    SELECT COUNT(*)
    INTO v_detail_count
    FROM payroll_runs pr
    INNER JOIN employee_payroll_details epd
        ON epd.payroll_run_id = pr.payroll_run_id
    WHERE pr.payroll_cycle_id = v_cycle_id;

    IF v_detail_count = 0 THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'No employee payroll details found for this cycle';

    END IF;

    /* =====================================================
       8. FINALIZE PAYROLL
       ===================================================== */

    IF v_action = 'FINALIZE' THEN

        /* Do not finalize a closed cycle */
        IF UPPER(COALESCE(v_cycle_status, ''))
            IN ('CLOSED', 'PAID') THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Paid or closed payroll cannot be finalized again';

        END IF;

        /* Runs must be approved or already finalized */
        SELECT COUNT(*)
        INTO v_invalid_count
        FROM payroll_runs
        WHERE payroll_cycle_id = v_cycle_id
          AND COALESCE(UPPER(run_status), '')
              NOT IN ('APPROVED', 'FINALIZED');

        IF v_invalid_count > 0 THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Cannot finalize: all payroll runs must be APPROVED or FINALIZED';

        END IF;

        /* Employee payroll records must be approved or finalized */
        SELECT COUNT(*)
        INTO v_invalid_count
        FROM payroll_runs pr
        INNER JOIN employee_payroll_details epd
            ON epd.payroll_run_id = pr.payroll_run_id
        WHERE pr.payroll_cycle_id = v_cycle_id
          AND (
                epd.net_pay IS NULL
                OR epd.net_pay < 0
                OR COALESCE(
                    UPPER(epd.employee_payroll_status), ''
                ) NOT IN ('APPROVED', 'FINALIZED')
              );

        IF v_invalid_count > 0 THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Cannot finalize: employee payroll records must be approved and net pay must be valid';

        END IF;

        /* Finalize employee payroll details */
        UPDATE employee_payroll_details epd
        INNER JOIN payroll_runs pr
            ON pr.payroll_run_id = epd.payroll_run_id
        SET epd.employee_payroll_status = 'FINALIZED'
        WHERE pr.payroll_cycle_id = v_cycle_id
          AND UPPER(epd.employee_payroll_status) = 'APPROVED';

        SET v_updated_count = ROW_COUNT();

        /* Finalize payroll runs */
        UPDATE payroll_runs
        SET
            run_status = 'FINALIZED',
            finalized_by = TRIM(p_requester_emp_id),
            finalized_at = NOW()
        WHERE payroll_cycle_id = v_cycle_id
          AND UPPER(run_status) = 'APPROVED';

        /* Finalize payroll cycle */
        UPDATE payroll_cycles
        SET
            cycle_status = 'FINALIZED',
            finalized_by = TRIM(p_requester_emp_id),
            finalized_at = NOW()
        WHERE payroll_cycle_id = v_cycle_id;

        SET v_remarks =
            'Payroll finalized successfully. Payroll sheet can be downloaded.';

    /* =====================================================
       9. MARK PAYROLL AS PAID
       ===================================================== */

    ELSEIF v_action = 'PAID' THEN

        /* Payroll must already be finalized or closed */
        IF UPPER(COALESCE(v_cycle_status, ''))
            NOT IN ('FINALIZED', 'CLOSED') THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Cannot mark as PAID: finalize payroll first';

        END IF;

        /* Every payroll run must be finalized */
        SELECT COUNT(*)
        INTO v_invalid_count
        FROM payroll_runs
        WHERE payroll_cycle_id = v_cycle_id
          AND COALESCE(UPPER(run_status), '') <> 'FINALIZED';

        IF v_invalid_count > 0 THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Cannot mark as PAID: all payroll runs must be FINALIZED';

        END IF;

        /* Every employee payroll record must be finalized */
        SELECT COUNT(*)
        INTO v_invalid_count
        FROM payroll_runs pr
        INNER JOIN employee_payroll_details epd
            ON epd.payroll_run_id = pr.payroll_run_id
        WHERE pr.payroll_cycle_id = v_cycle_id
          AND COALESCE(
                UPPER(epd.employee_payroll_status), ''
              ) <> 'FINALIZED';

        IF v_invalid_count > 0 THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                    'Cannot mark as PAID: all employee payroll records must be FINALIZED';

        END IF;

        /* Mark released employees as PAID and held employees ON_HOLD */
        UPDATE employee_payroll_details epd
        INNER JOIN payroll_runs pr
            ON pr.payroll_run_id = epd.payroll_run_id
        SET epd.payment_status =
            CASE
                WHEN UPPER(epd.payment_decision) = 'RELEASE'
                    THEN 'PAID'
                WHEN UPPER(epd.payment_decision) = 'HOLD'
                    THEN 'ON_HOLD'
            END
        WHERE pr.payroll_cycle_id = v_cycle_id
          AND UPPER(epd.payment_decision) IN ('RELEASE', 'HOLD');

        SET v_updated_count = ROW_COUNT();

        /* Close payroll cycle */
        UPDATE payroll_cycles
        SET
            cycle_status = 'CLOSED',
            closed_by = TRIM(p_requester_emp_id),
            closed_at = NOW()
        WHERE payroll_cycle_id = v_cycle_id
          AND UPPER(cycle_status) <> 'CLOSED';

        SET v_remarks =
            'Payroll marked as PAID. RELEASE employees marked PAID, HOLD employees marked ON_HOLD, and payroll cycle closed.';

    END IF;

    /* =====================================================
       10. COMMIT
       ===================================================== */

    COMMIT;

    SET v_transaction_started = 0;

    SET SESSION time_zone = v_old_time_zone;

    /* =====================================================
       11. RETURN RESULT
       ===================================================== */

    SELECT
        'Y' AS status,
        v_remarks AS remarks,
        v_action AS action_performed,
        v_cycle_id AS payroll_cycle_id,
        p_payroll_month AS payroll_month,
        p_payroll_year AS payroll_year,
        (
            SELECT cycle_status
            FROM payroll_cycles
            WHERE payroll_cycle_id = v_cycle_id
        ) AS current_status,
        v_updated_count AS employee_records_updated;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
