/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_update_component_master` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_update_component_master`(
    IN p_emp_id VARCHAR(20),
    IN p_action VARCHAR(20),
    IN p_component_id BIGINT,
    IN p_component_code VARCHAR(30),
    IN p_component_name VARCHAR(100),
    IN p_component_type VARCHAR(30),
    IN p_calculation_type VARCHAR(30),
    IN p_percentage_base VARCHAR(20),
    IN p_percentage_value DECIMAL(7,2),
    IN p_is_taxable TINYINT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_role VARCHAR(30);
    DECLARE v_actor_status VARCHAR(20);
    DECLARE v_component_exists INT DEFAULT 0;
    DECLARE v_affected INT DEFAULT 0;
    DECLARE v_master_updated INT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    /* 1. Validate requester */
    SELECT MAX(user_category), MAX(status)
    INTO v_role, v_actor_status
    FROM user_login_details
    WHERE emp_id = p_emp_id;

    IF v_role IS NULL
       OR LOWER(COALESCE(v_actor_status, '')) <> 'active'
       OR UPPER(v_role) NOT IN ('ADMIN', 'HR') THEN

        SELECT
            'N' AS status,
            'Only active ADMIN or HR users can manage components.'
                AS remarks;

    /* 2. Validate action */
    ELSEIF UPPER(COALESCE(p_action, '')) NOT IN
           ('INSERT', 'UPDATE', 'ACTIVE') THEN

        SELECT
            'N' AS status,
            'Invalid action. Use INSERT, UPDATE, or ACTIVE.'
                AS remarks;

    /* 3. Validate UPDATE inputs */
    ELSEIF UPPER(p_action) = 'UPDATE'
       AND (
            p_component_id IS NULL
            OR p_component_id <= 0
            OR p_component_code IS NULL
            OR TRIM(p_component_code) = ''
            OR p_component_name IS NULL
            OR TRIM(p_component_name) = ''
            OR UPPER(COALESCE(p_component_type, '')) NOT IN
                ('EARNING', 'DEDUCTION', 'EMPLOYER_CONTRIBUTION')
            OR UPPER(COALESCE(p_calculation_type, '')) NOT IN
                ('FIXED', 'PERCENTAGE', 'FORMULA', 'MANUAL', 'STATUTORY')
            OR UPPER(COALESCE(p_percentage_base, '')) NOT IN
                ('BASIC', 'GROSS', 'CTC', 'NONE')
            OR p_percentage_value IS NULL
            OR p_is_taxable IS NULL
            OR p_is_taxable NOT IN (0, 1)
            OR p_is_active IS NULL
            OR p_is_active NOT IN (0, 1)
       ) THEN

        SELECT
            'N' AS status,
            'Invalid or missing component details.'
                AS remarks;

    ELSE

        START TRANSACTION;

        /* =====================================================
           UPDATE MASTER COMPONENT
           ===================================================== */

        IF UPPER(p_action) = 'UPDATE' THEN

            SELECT COUNT(*)
            INTO v_component_exists
            FROM salary_component_master
            WHERE component_id = p_component_id;

            IF v_component_exists = 0 THEN

                SIGNAL SQLSTATE '45000'
                    SET MESSAGE_TEXT = 'Component not found.';

            END IF;

            /* Update master component */
            UPDATE salary_component_master
            SET
                component_code = p_component_code,
                component_name = p_component_name,
                component_type = UPPER(p_component_type),
                calculation_type = UPPER(p_calculation_type),
                percentage_base = UPPER(p_percentage_base),
                percentage_value = p_percentage_value,
                is_taxable = p_is_taxable,
                is_active = p_is_active
            WHERE component_id = p_component_id;

            SET v_master_updated = ROW_COUNT();

            /* =================================================
               SYNCHRONIZE ALL EMPLOYEE SALARY STRUCTURES

               IMPORTANT:
               - No is_overridden filter.
               - No salary structure status filter.
               - No effective date filter.
               - Previous calculation type does not matter.
               ================================================= */

            UPDATE employee_salary_structure ess

            INNER JOIN salary_structure ss
                ON ss.structure_id = ess.structure_id

            LEFT JOIN
            (
                SELECT
                    basic_ess.structure_id,
                    MAX(basic_ess.monthly_amount) AS basic_amount
                FROM employee_salary_structure basic_ess

                INNER JOIN salary_component_master basic_scm
                    ON basic_scm.component_id =
                       basic_ess.component_id

                WHERE basic_scm.component_code = 'BASIC'

                GROUP BY basic_ess.structure_id

            ) basic_data
                ON basic_data.structure_id = ss.structure_id

            SET

                /* Synchronize calculation type */
                ess.calculation_type =
                    CASE
                        WHEN UPPER(p_calculation_type) = 'STATUTORY'
                            THEN 'MANUAL'
                        ELSE UPPER(p_calculation_type)
                    END,

                /* Synchronize component value */
                ess.component_value = p_percentage_value,

                /* Synchronize percentage base */
                ess.percentage_base = UPPER(p_percentage_base),

                /* Recalculate or preserve monthly amount */
                ess.monthly_amount =
                    CASE

                        /* Percentage of CTC */
                        WHEN UPPER(p_calculation_type) = 'PERCENTAGE'
                             AND UPPER(p_percentage_base) = 'CTC'
                        THEN ROUND(
                            ss.monthly_ctc
                            * p_percentage_value / 100,
                            2
                        )

                        /* Percentage of BASIC */
                        WHEN UPPER(p_calculation_type) = 'PERCENTAGE'
                             AND UPPER(p_percentage_base) = 'BASIC'
                        THEN ROUND(
                            COALESCE(basic_data.basic_amount, 0)
                            * p_percentage_value / 100,
                            2
                        )

                        /*
                          FIXED and MANUAL:
                          Preserve the existing monthly amount.
                          The master table has no separate amount field.
                        */
                        WHEN UPPER(p_calculation_type)
                             IN ('FIXED', 'MANUAL', 'STATUTORY')
                        THEN ess.monthly_amount

                        /*
                          FORMULA:
                          Preserve the existing amount because
                          this procedure does not evaluate formulas.
                        */
                        WHEN UPPER(p_calculation_type) = 'FORMULA'
                        THEN ess.monthly_amount

                        /*
                          GROSS-based percentage:
                          Preserve the existing amount because
                          gross calculation is not implemented here.
                        */
                        ELSE ess.monthly_amount

                    END,

                ess.updated_at = CURRENT_TIMESTAMP

            WHERE ess.component_id = p_component_id;

            SET v_affected = ROW_COUNT();

            COMMIT;

            SELECT
                'Y' AS status,
                'Master component updated and employee component settings synchronized.'
                    AS remarks,
                p_component_id AS component_id,
                v_master_updated AS master_rows_changed,
                v_affected AS employee_structure_rows_changed;

        ELSEIF UPPER(p_action) = 'ACTIVE' THEN

            IF p_component_id IS NULL
               OR p_component_id <= 0
               OR p_is_active IS NULL
               OR p_is_active NOT IN (0, 1) THEN

                SIGNAL SQLSTATE '45000'
                    SET MESSAGE_TEXT =
                    'For ACTIVE, provide component_id and is_active (0 or 1).';

            END IF;

            UPDATE salary_component_master
            SET
                is_active = p_is_active,
                updated_at = CURRENT_TIMESTAMP
            WHERE component_id = p_component_id;

            IF ROW_COUNT() = 0 THEN

                SELECT COUNT(*)
                INTO v_component_exists
                FROM salary_component_master
                WHERE component_id = p_component_id;

                IF v_component_exists = 0 THEN

                    SIGNAL SQLSTATE '45000'
                        SET MESSAGE_TEXT = 'Component not found.';

                END IF;

            END IF;

            COMMIT;

            SELECT
                'Y' AS status,
                CASE
                    WHEN p_is_active = 1
                        THEN 'Component activated.'
                    ELSE 'Component deactivated.'
                END AS remarks,
                p_component_id AS component_id,
                p_is_active AS is_active;

        ELSEIF UPPER(p_action) = 'INSERT' THEN

            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT =
                'Use your existing INSERT procedure branch for component creation.';

        END IF;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_update_employee_salary_component` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_update_employee_salary_component`(
    IN p_emp_id VARCHAR(20),
    IN p_target_emp_id VARCHAR(20),
    IN p_component_id BIGINT,
    IN p_calculation_type VARCHAR(20),
    IN p_component_value DECIMAL(12,2),
    IN p_percentage_base VARCHAR(20),
    IN p_formula_expression VARCHAR(500)
)
BEGIN
    DECLARE v_role VARCHAR(30);
    DECLARE v_actor_status VARCHAR(20);
    DECLARE v_structure_id BIGINT;
    DECLARE v_ctc DECIMAL(12,2) DEFAULT 0;
    DECLARE v_basic DECIMAL(12,2) DEFAULT 0;
    DECLARE v_gross DECIMAL(12,2) DEFAULT 0;
    DECLARE v_amount DECIMAL(12,2) DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SELECT MAX(user_category), MAX(status)
    INTO v_role, v_actor_status
    FROM user_login_details
    WHERE emp_id = p_emp_id;

    IF v_role IS NULL
       OR LOWER(COALESCE(v_actor_status, '')) <> 'active'
       OR UPPER(v_role) NOT IN ('ADMIN', 'HR') THEN

        SELECT 'N' AS status,
               'Only active ADMIN or HR users can update employee salary.' AS remarks;

    ELSEIF p_target_emp_id IS NULL
       OR p_component_id IS NULL
       OR p_component_value IS NULL
       OR UPPER(p_calculation_type) NOT IN ('FIXED', 'PERCENTAGE', 'FORMULA', 'MANUAL')
       OR UPPER(p_percentage_base) NOT IN ('BASIC', 'GROSS', 'CTC', 'NONE') THEN

        SELECT 'N' AS status,
               'Invalid or missing employee component details.' AS remarks;

    ELSEIF NOT EXISTS (
        SELECT 1
        FROM user_login_details
        WHERE emp_id = p_target_emp_id
          AND LOWER(status) = 'active'
    ) THEN

        SELECT 'N' AS status,
               'Target employee does not exist or is inactive.' AS remarks;

    ELSEIF NOT EXISTS (
        SELECT 1
        FROM salary_component_master
        WHERE component_id = p_component_id
          AND is_active = 1
    ) THEN

        SELECT 'N' AS status,
               'Component not found or inactive.' AS remarks;

    ELSEIF NOT EXISTS (
        SELECT 1
        FROM salary_structure
        WHERE emp_id = p_target_emp_id
          AND structure_status = 'ACTIVE'
          AND effective_from <= CURDATE()
          AND (effective_to IS NULL OR effective_to >= CURDATE())
    ) THEN

        SELECT 'N' AS status,
               'Employee has no active salary structure.' AS remarks;

    ELSE

        SELECT structure_id, monthly_ctc
        INTO v_structure_id, v_ctc
        FROM salary_structure
        WHERE emp_id = p_target_emp_id
          AND structure_status = 'ACTIVE'
          AND effective_from <= CURDATE()
          AND (effective_to IS NULL OR effective_to >= CURDATE())
        ORDER BY effective_from DESC
        LIMIT 1;

        IF NOT EXISTS (
            SELECT 1
            FROM employee_salary_structure
            WHERE structure_id = v_structure_id
              AND component_id = p_component_id
        ) THEN

            SELECT 'N' AS status,
                   'Component is not assigned to this employee structure.' AS remarks;

        ELSE

            SELECT COALESCE((
                SELECT monthly_amount
                FROM employee_salary_structure
                WHERE structure_id = v_structure_id
                  AND component_id = (
                      SELECT component_id
                      FROM salary_component_master
                      WHERE component_code = 'BASIC'
                      LIMIT 1
                  )
                LIMIT 1
            ), 0)
            INTO v_basic;

            SELECT COALESCE(SUM(ess.monthly_amount), 0)
            INTO v_gross
            FROM employee_salary_structure ess
            JOIN salary_component_master scm
              ON scm.component_id = ess.component_id
            WHERE ess.structure_id = v_structure_id
              AND scm.component_type = 'EARNING'
              AND ess.component_id <> p_component_id;

            SET v_amount =
                CASE
                    WHEN UPPER(p_calculation_type) = 'FIXED'
                        THEN p_component_value

                    WHEN UPPER(p_calculation_type) = 'MANUAL'
                        THEN p_component_value

                    WHEN UPPER(p_calculation_type) = 'PERCENTAGE'
                         AND UPPER(p_percentage_base) = 'CTC'
                        THEN ROUND(v_ctc * p_component_value / 100, 2)

                    WHEN UPPER(p_calculation_type) = 'PERCENTAGE'
                         AND UPPER(p_percentage_base) = 'BASIC'
                        THEN ROUND(v_basic * p_component_value / 100, 2)

                    WHEN UPPER(p_calculation_type) = 'PERCENTAGE'
                         AND UPPER(p_percentage_base) = 'GROSS'
                        THEN ROUND(v_gross * p_component_value / 100, 2)

                    ELSE 0
                END;

            START TRANSACTION;

            UPDATE employee_salary_structure
            SET calculation_type = UPPER(p_calculation_type),
                component_value = p_component_value,
                percentage_base = UPPER(p_percentage_base),
                formula_expression = p_formula_expression,
                monthly_amount = v_amount,
                is_overridden = 1
            WHERE structure_id = v_structure_id
              AND component_id = p_component_id;

            COMMIT;

            SELECT 'Y' AS status,
                   'Employee component updated successfully.' AS remarks,
                   p_target_emp_id AS emp_id,
                   v_structure_id AS structure_id,
                   p_component_id AS component_id,
                   v_amount AS monthly_amount,
                   1 AS is_overridden;
        END IF;
    END IF;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_update_requests` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_update_requests`(
    IN p_action VARCHAR(20),          -- 'INSERT', 'UPDATE_PROGRESS', 'RESOLVE', 'COMPLETE', 'CANCEL'
    IN p_request_id BIGINT,           -- Target request ID (Pass NULL for 'INSERT')
    IN p_actor_emp_id VARCHAR(20),    -- Employee invoking the execution
    IN p_category VARCHAR(50),        -- Text string category (For INSERT)
    IN p_subject VARCHAR(255),        -- Text summary (For INSERT)
    IN p_description TEXT,            -- Full description block (For INSERT)
    IN p_attachment_path VARCHAR(255),-- Document link path (For INSERT, optional)
    IN p_progress VARCHAR(100),       -- Dynamic text note updates (For UPDATE_PROGRESS)
    IN p_reason VARCHAR(500)          -- Note details for Cancellation reason (For CANCEL)
)
main_block:BEGIN
    DECLARE v_emp_id VARCHAR(20);
    DECLARE v_status VARCHAR(20);
    DECLARE v_actor_category VARCHAR(20);

    SET time_zone = '+05:30';
    START TRANSACTION;

    -- Look up structural permissions category for the execution actor
    SELECT user_category INTO v_actor_category
    FROM user_login_details
    WHERE emp_id = p_actor_emp_id AND status = 'ACTIVE';

    -- ================= ACTION: INSERT =================
    IF p_action = 'INSERT' THEN
            emp_id, category, subject, description, attachment_path, progress, status
        ) VALUES (
            p_actor_emp_id, p_category, p_subject, p_description, p_attachment_path, 'Pending Assignment', 'PENDING'
        );
        
        COMMIT;
        SELECT 'Y' AS status, 'Request logged successfully' AS remarks;
        LEAVE main_block;
    END IF;

    -- For modifications/workflow steps, check existing target record state context
    SELECT emp_id, status INTO v_emp_id, v_status
    FROM general_requests WHERE request_id = p_request_id;

    IF v_emp_id IS NULL THEN
        ROLLBACK;
        SELECT 'N' AS status, 'Target request item record not found' AS remarks;
        LEAVE main_block;
    END IF;

    -- ================= ACTION: UPDATE_PROGRESS =================
    -- Allows HR or Admin to continuously post updates (1, 2, or more times) before resolution
    IF p_action = 'UPDATE_PROGRESS' THEN
        IF v_actor_category NOT IN ('HR', 'ADMIN') THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Not authorized. Only HR or ADMIN can add updates.' AS remarks;
            LEAVE main_block;
        END IF;

        UPDATE general_requests 
        SET progress = p_progress 
        WHERE request_id = p_request_id;
        
        COMMIT;
        SELECT 'Y' AS status, 'Progress string trace updated successfully' AS remarks;
        LEAVE main_block;
    END IF;

    -- ================= ACTION: RESOLVE =================
    -- Updates status from PENDING to RESOLVED when accepted by HR/Admin
    IF p_action = 'RESOLVE' THEN
        IF v_actor_category NOT IN ('HR', 'ADMIN') THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Not authorized. Only HR or ADMIN can change status to RESOLVED.' AS remarks;
            LEAVE main_block;
        END IF;

        IF v_status <> 'PENDING' THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Only PENDING requests can be transitioned to RESOLVED' AS remarks;
            LEAVE main_block;
        END IF;

        UPDATE general_requests 
        SET status = 'RESOLVED',
            resolved_id = p_actor_emp_id
        WHERE request_id = p_request_id;
        
        COMMIT;
        SELECT 'Y' AS status, 'Request accepted and marked as RESOLVED' AS remarks;
        LEAVE main_block;
    END IF;

    -- ================= ACTION: COMPLETE =================
    -- Employee transitions state to COMPLETED after verifying HR/Admin resolution
    IF p_action = 'COMPLETE' THEN
        IF p_actor_emp_id <> v_emp_id THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Access Denied. Only the owning employee can mark this request complete' AS remarks;
            LEAVE main_block;
        END IF;

        IF v_status <> 'RESOLVED' THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Requests must be in RESOLVED state before closing out as COMPLETED' AS remarks;
            LEAVE main_block;
        END IF;

        UPDATE general_requests 
        SET status = 'COMPLETED' 
        WHERE request_id = p_request_id;
        
        COMMIT;
        SELECT 'Y' AS status, 'Workflow state marked COMPLETED by employee' AS remarks;
        LEAVE main_block;
    END IF;

    -- ================= ACTION: CANCEL =================
    -- Allows the owning employee to pull out/drop a pending item
    IF p_action = 'CANCEL' THEN
        IF p_actor_emp_id <> v_emp_id THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Only the original applicant can cancel this request' AS remarks;
            LEAVE main_block;
        END IF;

        IF v_status IN ('RESOLVED', 'COMPLETED') THEN
            ROLLBACK;
            SELECT 'N' AS status, 'Cannot cancel requests that have already been processed or completed' AS remarks;
            LEAVE main_block;
        END IF;

        UPDATE general_requests 
        SET status = 'CANCELLED',
            reason = p_reason 
        WHERE request_id = p_request_id;
        
        COMMIT;
        SELECT 'Y' AS status, 'Request successfully CANCELLED' AS remarks;
        LEAVE main_block;
    END IF;

    -- Handling structural faults/incorrect operational parameter routes
    ROLLBACK;
    SELECT 'N' AS status, 'Invalid context mutation parameter operation action execution' AS remarks;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `hrms_update_salary_structure` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hrms_update_salary_structure`(
    IN p_emp_id VARCHAR(20),
    IN p_target_emp_id VARCHAR(20),
    IN p_monthly_ctc DECIMAL(12,2),
    IN p_effective_from DATE
)
BEGIN
    DECLARE v_role VARCHAR(30);
    DECLARE v_actor_status VARCHAR(20);
    DECLARE v_structure_id BIGINT DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    /* Validate requester */

    SELECT MAX(user_category), MAX(status)
    INTO v_role, v_actor_status
    FROM user_login_details
    WHERE emp_id = p_emp_id;

    IF v_role IS NULL
       OR LOWER(COALESCE(v_actor_status, '')) <> 'active'
       OR UPPER(v_role) NOT IN ('ADMIN', 'HR') THEN

        SELECT 'N' AS status,
               'Only active ADMIN or HR users can revise salary.' AS remarks;

    /* Validate input */

    ELSEIF p_target_emp_id IS NULL
       OR TRIM(p_target_emp_id) = ''
       OR p_monthly_ctc IS NULL
       OR p_monthly_ctc <= 0 THEN

        SELECT 'N' AS status,
               'Provide a valid employee ID and positive monthly CTC.' AS remarks;

    ELSEIF p_effective_from IS NULL THEN

        SELECT 'N' AS status,
               'Effective from date is required.' AS remarks;

    /* Validate target employee */

    ELSEIF NOT EXISTS (
        SELECT 1
        FROM user_login_details
        WHERE emp_id = p_target_emp_id
          AND LOWER(status) = 'active'
    ) THEN

        SELECT 'N' AS status,
               'Target employee does not exist or is inactive.' AS remarks;

    ELSE

        /* Find the salary structure effective on the requested date */

        SELECT MAX(structure_id)
        INTO v_structure_id
        FROM salary_structure
        WHERE emp_id = p_target_emp_id
          AND structure_status = 'ACTIVE'
          AND effective_from <= p_effective_from
          AND (
              effective_to IS NULL
              OR effective_to >= p_effective_from
          );

        IF v_structure_id IS NULL THEN

            SELECT 'N' AS status,
                   'No active salary structure exists for the selected effective date.' AS remarks;

        ELSE

            START TRANSACTION;

            /* Update salary structure */

            UPDATE salary_structure
            SET monthly_ctc = p_monthly_ctc,
                annual_ctc = p_monthly_ctc * 12,
                effective_from = p_effective_from
            WHERE structure_id = v_structure_id;

            /* Recalculate CTC-based components */

            UPDATE employee_salary_structure ess
            JOIN salary_component_master scm
                ON scm.component_id = ess.component_id
            SET ess.monthly_amount =
                ROUND(
                    p_monthly_ctc * ess.component_value / 100,
                    2
                )
            WHERE ess.structure_id = v_structure_id
              AND ess.is_overridden = 0
              AND ess.calculation_type = 'PERCENTAGE'
              AND ess.percentage_base = 'CTC';

            /* Recalculate BASIC-based components */

            UPDATE employee_salary_structure ess
            JOIN salary_component_master scm
                ON scm.component_id = ess.component_id
            SET ess.monthly_amount =
                ROUND(
                    COALESCE((
                        SELECT basic_ess.monthly_amount
                        FROM employee_salary_structure basic_ess
                        JOIN salary_component_master basic_scm
                            ON basic_scm.component_id =
                               basic_ess.component_id
                        WHERE basic_ess.structure_id =
                              ess.structure_id
                          AND basic_scm.component_code = 'BASIC'
                        LIMIT 1
                    ), 0) * ess.component_value / 100,
                    2
                )
            WHERE ess.structure_id = v_structure_id
              AND ess.is_overridden = 0
              AND ess.calculation_type = 'PERCENTAGE'
              AND ess.percentage_base = 'BASIC'
              AND scm.component_code <> 'BASIC';

            /* Recalculate GROSS-based components */

            UPDATE employee_salary_structure ess
            JOIN salary_component_master scm
                ON scm.component_id = ess.component_id
            SET ess.monthly_amount =
                ROUND(
                    COALESCE((
                        SELECT SUM(gross_ess.monthly_amount)
                        FROM employee_salary_structure gross_ess
                        JOIN salary_component_master gross_scm
                            ON gross_scm.component_id =
                               gross_ess.component_id
                        WHERE gross_ess.structure_id =
                              ess.structure_id
                          AND gross_scm.component_type = 'EARNING'
                          AND gross_ess.component_id <> ess.component_id
                    ), 0) * ess.component_value / 100,
                    2
                )
            WHERE ess.structure_id = v_structure_id
              AND ess.is_overridden = 0
              AND ess.calculation_type = 'PERCENTAGE'
              AND ess.percentage_base = 'GROSS';

            COMMIT;

            /* Success response */

            SELECT
                'Y' AS status,
                'Salary structure updated successfully.' AS remarks,
                p_target_emp_id AS emp_id,
                v_structure_id AS structure_id,
                p_monthly_ctc AS monthly_ctc,
                p_monthly_ctc * 12 AS annual_ctc,
                p_effective_from AS effective_from;

        END IF;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
