CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_announcement_get`(
    IN p_actor_emp_id VARCHAR(20)
)
main_block:BEGIN

    DECLARE v_actor_category VARCHAR(20);
    DECLARE v_record_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- Identify who is looking at the announcements
    SELECT user_category INTO v_actor_category 
    FROM user_login_details 
    WHERE emp_id = p_actor_emp_id AND status = 'ACTIVE';

    -- 1. Check if user profile is valid
    IF v_actor_category IS NULL THEN
        SELECT 'N' AS status, 'Invalid or inactive user profile' AS remarks;
        LEAVE main_block;
    END IF;

    -- Count matching announcements based on role hierarchy and visibility rules
    SELECT COUNT(*) INTO v_record_count
    FROM announcements a
    WHERE 
        -- HR and ADMIN see everything
        (v_actor_category IN ('HR', 'ADMIN'))
        
        -- Managers see ACTIVE announcements targeted to MANAGER, EMP, INTERN, or ALL
        OR (v_actor_category = 'MANAGER' AND a.status = 'ACTIVE' AND a.user_category IN ('MANAGER', 'EMP', 'INTERN', 'ALL'))
        
        -- Regular Employees see ACTIVE announcements targeted to EMP or ALL
        OR (v_actor_category = 'EMP' AND a.status = 'ACTIVE' AND a.user_category IN ('EMP', 'ALL'))
        
        -- Interns see ACTIVE announcements targeted specifically to INTERN or ALL
        OR (v_actor_category = 'INTERN' AND a.status = 'ACTIVE' AND a.user_category IN ('INTERN', 'ALL'));

    -- 2. If no announcements are available, return standard 'N' structure
    IF v_record_count = 0 THEN
        SELECT 'N' AS status, 'No announcements available' AS remarks;
        LEAVE main_block;
    END IF;

    -- 3. If records exist, return 'Y' as status alongside data rows
    SELECT 
        'Y' AS status,
        'Success' AS remarks,
        a.announcement_id AS AnnouncementID,
        a.title AS Title,
        a.user_category AS UserCategory,
        a.message AS Message,
        a.status AS Status,
        a.created_on AS CreatedOn,
        a.updated_on AS UpdatedOn
    FROM announcements a
    WHERE 
        -- HR and ADMIN see everything (both ACTIVE and INACTIVE records)
        (v_actor_category IN ('HR', 'ADMIN'))
        
        -- Managers see ACTIVE announcements matching MANAGER, EMP, INTERN, or ALL
        OR (v_actor_category = 'MANAGER' AND a.status = 'ACTIVE' AND a.user_category IN ('MANAGER', 'EMP', 'INTERN', 'ALL'))
        
        -- Regular Employees see ACTIVE announcements matching EMP or ALL
        OR (v_actor_category = 'EMP' AND a.status = 'ACTIVE' AND a.user_category IN ('EMP', 'ALL'))
        
        -- Interns see ACTIVE announcements matching INTERN or ALL
        OR (v_actor_category = 'INTERN' AND a.status = 'ACTIVE' AND a.user_category IN ('INTERN', 'ALL'))
    ORDER BY a.created_on DESC;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
