CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_approve_candidate`(
    IN p_ref_id VARCHAR(20),
    IN p_approver_emp_id VARCHAR(20)
)
BEGIN

    DECLARE v_count INT DEFAULT 0;
    DECLARE v_email VARCHAR(100);
    DECLARE v_approved_count INT DEFAULT 0;
    DECLARE v_emp_id VARCHAR(20);
    DECLARE v_password VARCHAR(20);
    DECLARE v_error_message TEXT;
    DECLARE v_approver_role VARCHAR(20) DEFAULT NULL;
    DECLARE v_candidate_type VARCHAR(20) DEFAULT NULL;
    DECLARE v_next_num INT DEFAULT 0;

    -- Exception Handler
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            v_error_message = MESSAGE_TEXT;

        ROLLBACK;

        SELECT
            'N' AS status,
            NULL AS emp_id,
            v_error_message AS remarks;
    END;

    -- Set local Time Zone
    SET time_zone = '+05:30';

    -- 1. Check if the Approver has HR or ADMIN privileges
    SELECT user_category 
    INTO v_approver_role
    FROM user_login_details
    WHERE emp_id = p_approver_emp_id
      AND status = 'ACTIVE'
    LIMIT 1;

    IF v_approver_role IS NULL OR v_approver_role NOT IN ('HR', 'ADMIN') THEN
        
        SELECT
            'N' AS status,
            NULL AS emp_id,
            'Unauthorized: Only ACTIVE users with HR or ADMIN roles can approve candidates' AS remarks;

    ELSE

        -- 2. Fetch candidate email and type
        SELECT 
            IFNULL(email, ''), 
            candidate_type
        INTO 
            v_email, 
            v_candidate_type
        FROM candidate_details
        WHERE ref_id = p_ref_id
        LIMIT 1;

        -- 3. Check if candidate is already approved
        SELECT COUNT(*)
        INTO v_approved_count
        FROM candidate_details
        WHERE ref_id = p_ref_id
          AND hr_status = 'APPROVED';

        IF v_approved_count > 0 THEN

            SELECT
                'N' AS status,
                NULL AS emp_id,
                'candidate already approved' AS remarks;

        ELSE

            -- 4. Check if candidate has completed Step 6
            SELECT COUNT(*)
            INTO v_count
            FROM candidate_details
            WHERE ref_id = p_ref_id
              AND current_step = 6;

            IF v_count > 0 THEN

                START TRANSACTION;

                -- 5. Sequential Employee ID Generation based on Candidate Type
                IF v_candidate_type = 'INTERN' THEN
                    -- Filter for 'INT0' prefix and 8 total characters (INT + 5 digits)
                    SELECT IFNULL(MAX(CAST(SUBSTRING(emp_id, 4) AS UNSIGNED)), 0) + 1
                    INTO v_next_num
                    FROM user_details
                    WHERE emp_id LIKE 'INT0%' AND LENGTH(emp_id) = 8;

                    SET v_emp_id = CONCAT('INT', LPAD(v_next_num, 5, '0'));
                ELSE
                    -- Filter for 'BS0' prefix and 7 total characters (BS + 5 digits)
                    SELECT IFNULL(MAX(CAST(SUBSTRING(emp_id, 3) AS UNSIGNED)), 0) + 1
                    INTO v_next_num
                    FROM user_details
                    WHERE emp_id LIKE 'BS0%' AND LENGTH(emp_id) = 7;

                    -- Generates format BS00291, BS00292, etc.
                    SET v_emp_id = CONCAT('BS', LPAD(v_next_num, 5, '0'));
                END IF;

                SET v_password = 'Welcome@123';

                -- Migrate data to user_details
                    ref_id,
                    emp_id,
                    emp_name,
                    email,
                    mobile,
                    dob,
                    gender,
                    marital_status,
                    father_name,
                    mother_name,
                    current_address,
                    perminent_address,
                    bank_holder_name,
                    bank_name,
                    bank_branch,
                    bank_account_no,
                    ifsc,
                    upi_id,
                    bank_account_type,
                    pan,
                    aadhaar,
                    uan,
                    skills,
                    qualification,
                    experience,
                    documents,
                    department,
                    designation,
                    reporting,
                    joining_date,
                    received_on,
                    updated_on
                )
                SELECT
                    p_ref_id,
                    v_emp_id,
                    emp_name,
                    email,
                    mobile,
                    dob,
                    gender,
                    marital_status,
                    father_name,
                    mother_name,
                    current_address,
                    perminent_address,
                    bank_holder_name,
                    bank_name,
                    bank_branch,
                    bank_account_no,
                    ifsc,
                    upi_id,
                    bank_account_type,
                    pan,
                    Aadhaar,
                    uan,
                    skills,
                    qualification,
                    experience,
                    documents,
                    department,
                    designation,
                    reporting,
                    joining_date,
                    NOW(),
                    NOW()
                FROM candidate_details
                WHERE ref_id = p_ref_id;

                -- Create record in user_login_details
                    emp_id,
                    enc_pwd,
                    user_category,
                    is_first_login,
                    status,
                    received_on,
                    updated_on
                )
                SELECT
                    v_emp_id,
                    v_password,
                    candidate_type,
                    1,
                    'ACTIVE',
                    NOW(),
                    NOW()
                FROM candidate_details
                WHERE ref_id = p_ref_id;

                -- Update candidate onboarding status
                UPDATE candidate_details
                SET
                    hr_status = 'APPROVED',
                    onboarding_status = 'COMPLETED',
                    current_step = 6,
                    remarks = CONCAT('Employee Created : ', v_emp_id, ' by ', p_approver_emp_id),
                    updated_on = NOW()
                WHERE ref_id = p_ref_id;

                -- Generate leave balances for the present year (2026)
                CALL hrmstest.hr_generate_leave_balances(2026);

                COMMIT;

                -- Success Output Response
                SELECT
                    'Y' AS status,
                    v_emp_id AS emp_id,
                    v_password AS password,
                    v_email AS email,
                    'employee created successfully' AS remarks;

            ELSE

                SELECT
                    'N' AS status,
                    NULL AS emp_id,
                    'candidate has not completed step 6' AS remarks;

            END IF;

        END IF;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
