/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_create_candidate`(
    IN p_candidate_type VARCHAR(20),
    IN p_emp_name VARCHAR(150),
    IN p_email VARCHAR(150),
    IN p_mobile VARCHAR(15),
    IN p_experience VARCHAR(50),
    IN p_offer_letter_url TEXT,
    IN p_created_by VARCHAR(20)
)
BEGIN

    DECLARE v_count INT DEFAULT 0;
    DECLARE v_ref_id VARCHAR(20);
    DECLARE v_password VARCHAR(20);

    SET time_zone = '+05:30';

    -- Check duplicate email in both candidate_details and user_details
    SELECT 
        (SELECT COUNT(*) FROM candidate_details WHERE email = p_email) +
        (SELECT COUNT(*) FROM user_details WHERE email = p_email)
    INTO v_count;

    IF v_count = 0 THEN

        -- Generate ref id
        SET v_ref_id = CONCAT(
            'REF',
            FLOOR(100000 + RAND() * 900000)
        );

        -- Generate password
        SET v_password = SUBSTRING(MD5(RAND()), 1, 8);

        -- Insert candidate
            ref_id,
            candidate_type,
            application_source,
            temp_password,
            offer_letter_url,
            emp_name,
            email,
            mobile,
            experience,
            created_by,
            hr_status
        )
        VALUES (
            v_ref_id,
            p_candidate_type,
            'HR',
            v_password,
            p_offer_letter_url,
            p_emp_name,
            p_email,
            p_mobile,
            p_experience,
            p_created_by,
            'SELECTED'
        );

        -- Success response
        SELECT
            'Y' AS status,
            v_ref_id AS ref_id,
            v_password AS password,
            p_email AS email,
            'candidate created successfully' AS remarks;

    ELSE

        -- Duplicate email found
        SELECT
            'N' AS status,
            NULL AS ref_id,
            NULL AS password,
            'email already exists' AS remarks;

    END IF;

END
;;
DELIMITER ;
