/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_generate_leave_balances`(
    IN p_year INT
)
BEGIN
    SET time_zone = '+05:30';

        emp_id,
        leave_type_id,
        year,
        opening_balance,
        credited,
        availed,
        closing_balance,
        received_on,
        updated_on
    )
    SELECT
        u.emp_id,
        l.leave_type_id,
        p_year,

        /* No Carry Forward */
        0.00 AS opening_balance,

        /* Credited Leave */
        CASE

            /* Existing employees */
            WHEN YEAR(u.joining_date) < p_year THEN
                l.yearly_quota

            /* Joined during current year */
            WHEN YEAR(u.joining_date) = p_year THEN
                ROUND(
                    l.yearly_quota *
                    ((12 - MONTH(u.joining_date)) + 1) / 12,
                    0
                )

            ELSE
                0
        END AS credited,

        0.00 AS availed,

        /* Closing Balance */
        CASE

            WHEN YEAR(u.joining_date) < p_year THEN
                l.yearly_quota

            WHEN YEAR(u.joining_date) = p_year THEN
                ROUND(
                    l.yearly_quota *
                    ((12 - MONTH(u.joining_date)) + 1) / 12,
                    0
                )

            ELSE
                0
        END AS closing_balance,

        NOW(),
        NOW()

    FROM user_details u

    INNER JOIN user_login_details ul
        ON ul.emp_id = u.emp_id
       AND LOWER(TRIM(ul.status)) = 'active'

    INNER JOIN leave_type l
        ON l.year = p_year
       AND LOWER(TRIM(l.status)) IN ('a','active')

       /* Skip ML balance generation */
       AND l.leave_code <> 'ML'

       /* Generate balances only for these leave types */
       AND l.leave_code IN ('PL','SL','WFH','LOP')

       /* Intern Rules */
       AND (
            (
                UPPER(ul.user_category)='INTERN'
                AND l.leave_code IN ('PL','LOP')
            )
            OR
            (
                UPPER(ul.user_category)<>'INTERN'
            )
       )

    WHERE u.joining_date IS NOT NULL
      AND YEAR(u.joining_date) <= p_year

      AND NOT EXISTS
      (
          SELECT 1
          FROM emp_leave_balance b
          WHERE b.emp_id = u.emp_id
            AND b.leave_type_id = l.leave_type_id
            AND b.year = p_year
      );

    SELECT
        'Y' AS status,
        CONCAT('Leave balances generated successfully for year ', p_year) AS remarks;

END
;;
DELIMITER ;
