CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_get_departments`()
BEGIN
    SET time_zone = '+05:30';

    SELECT 
        'Y' AS status,
        'Success' AS remarks,
        dm.department_id,
        dm.department_name,
        dm.status,
        COUNT(ud.id) AS member_count,
        dm.received_on,
        dm.updated_on
    FROM department_master dm
    LEFT JOIN user_details ud
        ON ud.department = dm.department_id
    GROUP BY
        dm.department_id,
        dm.department_name,
        dm.status,
        dm.received_on,
        dm.updated_on
    ORDER BY dm.department_name ASC;

END
;;
