CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_get_employee_details`(
    IN p_emp_id VARCHAR(20),
    IN p_role VARCHAR(20),
    IN p_search_emp_id VARCHAR(20)
)
BEGIN

    SET time_zone = '+05:30';

    /*
        SUCCESS CASE
    */
    IF EXISTS (
        SELECT 1
        FROM user_details u

        INNER JOIN (
            SELECT emp_id, MAX(status) AS status
            FROM user_login_details
            GROUP BY emp_id
        ) ul
            ON ul.emp_id = u.emp_id

        WHERE
        (
            (
                p_role IN ('MANAGER', 'EMP', 'HR')
                AND u.reporting = p_emp_id
            )
            OR
            (
                p_role = 'ADMIN'
            )
        )
        AND
        (
            p_search_emp_id = 'ALL'
            OR u.emp_id = p_search_emp_id
        )
    )
    THEN

        SELECT
            'Y' AS status,
            'Success' AS remarks,
            u.id,
            u.emp_id,
            u.ref_id,
            u.emp_name,
            u.email,
            u.mobile,
            u.dob,
            u.gender,
            u.marital_status,
            u.father_name,
            u.mother_name,
            u.current_address,
            u.perminent_address,

            u.department AS department_id,
            IFNULL(d.department_name, 'Department Not Available') AS department_name,
            IFNULL(d.status, '') AS department_status,

            u.designation,
            u.reporting,
            IFNULL(r.emp_name, '') AS reporting_name,
            u.joining_date,
            u.skills,
            u.qualification,
            u.experience,
            u.bank_holder_name,
            u.bank_name,
            u.bank_branch,
            u.bank_account_no,
            u.ifsc,
            u.upi_id,
            u.bank_account_type,
            u.pan,
            u.aadhaar,
            u.uan,
            u.documents,
            u.received_on,
            u.updated_on,

            ul.status AS employee_login_status,

            total_counts.total_employee_count

        FROM user_details u

        INNER JOIN (
            SELECT emp_id, MAX(status) AS status
            FROM user_login_details
            GROUP BY emp_id
        ) ul
            ON ul.emp_id = u.emp_id

        LEFT JOIN department_master d
            ON d.department_id = u.department

        LEFT JOIN user_details r
            ON r.emp_id = u.reporting

        CROSS JOIN (
            SELECT COUNT(DISTINCT ud.emp_id) AS total_employee_count
            FROM user_details ud
            INNER JOIN user_login_details uld
                ON ud.emp_id = uld.emp_id
        ) total_counts

        WHERE
        (
            (
                p_role IN ('MANAGER', 'EMP', 'HR')
                AND u.reporting = p_emp_id
            )
            OR
            (
                p_role = 'ADMIN'
            )
        )
        AND
        (
            p_search_emp_id = 'ALL'
            OR u.emp_id = p_search_emp_id
        )

        ORDER BY u.joining_date;

    ELSE

        /*
            NO DATA CASE
        */
        SELECT
            'N' AS status,
            'No employee details found' AS remarks,
		

            (
                SELECT COUNT(DISTINCT ud.emp_id)
                FROM user_details ud
                INNER JOIN user_login_details uld
                    ON ud.emp_id = uld.emp_id
            ) AS total_employee_count;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
