CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_reject_candidate`(

    IN p_ref_id VARCHAR(20),

    IN p_remarks LONGTEXT

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    DECLARE v_offer_status VARCHAR(20);

    DECLARE v_hr_status VARCHAR(20);

    SET time_zone = '+05:30';

    -- validate candidate

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE ref_id = p_ref_id;

    IF v_count > 0 THEN

        -- get statuses

        SELECT
            IFNULL(offer_status,''),
            IFNULL(hr_status,'')
        INTO
            v_offer_status,
            v_hr_status
        FROM candidate_details
        WHERE ref_id = p_ref_id;

        -- already approved

        IF v_hr_status = 'APPROVED' THEN

            SELECT
                'N' AS status,
                p_ref_id AS ref_id,
                'candidate already approved' AS remarks;

        -- already accepted offer

        ELSEIF v_offer_status = 'ACCEPTED' THEN

            SELECT
                'N' AS status,
                p_ref_id AS ref_id,
                'candidate already accepted offer letter' AS remarks;

        ELSE

            -- reject candidate

            UPDATE candidate_details
            SET
                hr_status = 'REJECTED',
                onboarding_status = 'REJECTED',
                remarks = p_remarks,
                updated_on = NOW()
            WHERE ref_id = p_ref_id;

            -- success response

            SELECT
                'Y' AS status,
                p_ref_id AS ref_id,
                p_remarks AS remarks;

        END IF;

    ELSE

        SELECT
            'N' AS status,
            p_ref_id AS ref_id,
            'candidate not found' AS remarks;

    END IF;

END
;;
DELIMITER ;
