CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `hr_toggle_user_status`(
    IN p_admin_emp_id VARCHAR(20),   -- ID of the person making the change
    IN p_admin_category VARCHAR(20), -- Role of the person making the change (ADMIN or HR)
    IN p_target_emp_id VARCHAR(20)   -- The employee ID to flip
)
BEGIN
    DECLARE v_current_status VARCHAR(20);
    DECLARE v_new_status VARCHAR(20);

    SET time_zone = '+05:30';

    -- 1. Strictly enforce Role-Based Access Security
    IF p_admin_category IN ('ADMIN', 'HR') THEN
        
        -- 2. Fetch the user's current status if they exist
        SELECT status INTO v_current_status
        FROM user_login_details
        WHERE emp_id = p_target_emp_id;

        -- 3. If a record was found, determine the inverse status dynamically
        IF v_current_status IS NOT NULL THEN
            
            -- If ACTIVE, flip to INACTIVE. Otherwise, flip to ACTIVE.
            IF v_current_status = 'ACTIVE' THEN
                SET v_new_status = 'INACTIVE';
            ELSE
                SET v_new_status = 'ACTIVE';
            END IF;

            -- 4. Execute the dynamic status update
            UPDATE user_login_details
            SET status = v_new_status,
                updated_on = NOW()
            WHERE emp_id = p_target_emp_id;

            -- Return confirmation payload
            SELECT 
                'Y' AS status,
                CONCAT('Success: Employee ', p_target_emp_id, ' changed from ', v_current_status, ' to ', v_new_status, '.') AS remarks;

        ELSE
            -- Target user record doesn't exist
            SELECT 
                'N' AS status,
                CONCAT('Failure: Employee ID ', p_target_emp_id, ' was not found in user login records.') AS remarks;
        END IF;

    ELSE
        -- Return Access Denied Failure Flag
        SELECT 
            'N' AS status,
            'Access Denied: Status modifications are restricted to ADMIN or HR roles only.' AS remarks;
            
    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
