CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `select_salary_by_id`(in p_staff_id varchar(400))
begin
    select distinct 
        st.*,
        sft.emp_name,
        sft.current_address,
        sft.mobile,
        sft.email,
        dt.department_name
    from salary_tbl st
    join user_details sft on sft.emp_id = st.staff_id
    join department_master dt on dt.department_id = sft.department
    join user_login_details ud on st.staff_id = ud.emp_id and ud.status = 'Active'
    where st.staff_id = p_staff_id
    limit 1;
end
;;
