CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `select_salary_by_staff_id`(IN p_staff_id VARCHAR(400))
BEGIN
    SELECT DISTINCT 
        st.*,
        sft.emp_name,
        sft.current_address,
        sft.mobile,
        sft.email,
        dt.department_name
    FROM salary_tbl st
    JOIN user_details sft ON sft.emp_id = st.staff_id
    JOIN department_master dt ON dt.department_id = sft.department
    JOIN user_login_details ud ON sft.emp_id = ud.emp_id AND ud.status = 'Active'
    WHERE st.staff_id = p_staff_id
    LIMIT 1;
END
;;
