CREATE DEFINER=`hrmstest`@`%` PROCEDURE `sp_department_cud`(
        IN p_mode VARCHAR(10),
        IN p_department_id INT,
        IN p_department_name VARCHAR(100),
        IN p_status CHAR(1)
    )
BEGIN
        SET time_zone = '+05:30';

        IF p_mode = 'INSERT' THEN
            VALUES (p_department_name, COALESCE(p_status, '1'), NOW(), NOW());
            
            SELECT 'Y' AS status, 'Department created successfully' AS remarks, LAST_INSERT_ID() AS id;

        ELSEIF p_mode = 'UPDATE' THEN
            UPDATE department_master
            SET department_name = COALESCE(p_department_name, department_name),
                status = COALESCE(p_status, status),
                updated_on = NOW()
            WHERE department_id = p_department_id;
            
            SELECT 'Y' AS status, 'Department updated successfully' AS remarks, p_department_id AS id;

        ELSEIF p_mode = 'DELETE' THEN
            UPDATE department_master
            SET status = '0',
                updated_on = NOW()
            WHERE department_id = p_department_id;
            
            SELECT 'Y' AS status, 'Department deleted successfully' AS remarks, p_department_id AS id;

        ELSE
            SELECT 'N' AS status, 'Invalid mode' AS remarks, NULL AS id;
        END IF;
    END
;;
DELIMITER ;
