/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `sp_generate_payroll_attendance`(
    IN p_month INT,
    IN p_year INT,
    IN p_admin_emp_id VARCHAR(20)
)
main_block: BEGIN

    DECLARE done INT DEFAULT FALSE;

    DECLARE v_emp_id VARCHAR(20);
    DECLARE v_admin_category VARCHAR(20);

    DECLARE v_start_date DATE;
    DECLARE v_end_date DATE;
    DECLARE v_month_start DATE;
    DECLARE v_previous_month DATE;

    DECLARE v_start_day INT;
    DECLARE v_end_day INT;

    DECLARE v_finalized_count INT DEFAULT 0;
    DECLARE v_generated_count INT DEFAULT 0;

    DECLARE v_total_days DECIMAL(5,2) DEFAULT 0;
    DECLARE v_working_days DECIMAL(5,2) DEFAULT 0;

    DECLARE v_present DECIMAL(5,2) DEFAULT 0;
    DECLARE v_wfh DECIMAL(5,2) DEFAULT 0;
    DECLARE v_leave DECIMAL(5,2) DEFAULT 0;
    DECLARE v_holiday DECIMAL(5,2) DEFAULT 0;
    DECLARE v_weekoff DECIMAL(5,2) DEFAULT 0;
    DECLARE v_absent DECIMAL(5,2) DEFAULT 0;

    DECLARE v_late INT DEFAULT 0;
    DECLARE v_half_days DECIMAL(5,2) DEFAULT 0;
    DECLARE v_overtime DECIMAL(6,2) DEFAULT 0;

    DECLARE v_paid DECIMAL(5,2) DEFAULT 0;
    DECLARE v_unpaid DECIMAL(5,2) DEFAULT 0;

    DECLARE v_error_no INT DEFAULT 0;
    DECLARE v_error_message TEXT;

    /*
      Process each active employee once, even if duplicate active
      login records exist for the same employee.
    */
    DECLARE emp_cursor CURSOR FOR
        SELECT DISTINCT TRIM(emp_id)
        FROM user_login_details
        WHERE UPPER(TRIM(status)) = 'ACTIVE'
          AND emp_id IS NOT NULL
          AND TRIM(emp_id) <> ''
        ORDER BY TRIM(emp_id);

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET done = TRUE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN

        GET DIAGNOSTICS CONDITION 1
            v_error_no = MYSQL_ERRNO,
            v_error_message = MESSAGE_TEXT;

        ROLLBACK;

        SELECT
            'N' AS status,
            CONCAT(
                'Database error [',
                COALESCE(v_error_no, 0),
                ']: ',
                COALESCE(v_error_message, 'Unknown error')
            ) AS message;

    END;

    SET time_zone = '+05:30';

    /* 1. Validate admin employee ID */

    IF p_admin_emp_id IS NULL
       OR TRIM(p_admin_emp_id) = '' THEN

        SELECT
            'N' AS status,
            'Admin Employee ID is required.' AS message;

        LEAVE main_block;

    END IF;

    /* 2. Validate payroll month and year */

    IF p_month IS NULL
       OR p_month NOT BETWEEN 1 AND 12
       OR p_year IS NULL
       OR p_year NOT BETWEEN 1900 AND 9999 THEN

        SELECT
            'N' AS status,
            'Invalid payroll month or year.' AS message;

        LEAVE main_block;

    END IF;

    /* 3. Validate active ADMIN or HR user */

    SET v_admin_category = NULL;

    SELECT MAX(UPPER(TRIM(user_category)))
    INTO v_admin_category
    FROM user_login_details
    WHERE emp_id = TRIM(p_admin_emp_id)
      AND UPPER(TRIM(status)) = 'ACTIVE';

    IF v_admin_category IS NULL
       OR v_admin_category NOT IN ('ADMIN', 'HR') THEN

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Access denied. Only active ADMIN or HR can generate payroll attendance.';

    END IF;

    /* 4. Read payroll cycle configuration */

    SET v_start_day = NULL;
    SET v_end_day = NULL;

    SELECT
        payroll_cycle_start_day,
        payroll_cycle_end_day
    INTO
        v_start_day,
        v_end_day
    FROM company_settings
    ORDER BY id
    LIMIT 1;

    IF v_start_day IS NULL
       OR v_end_day IS NULL
       OR v_start_day NOT BETWEEN 1 AND 31
       OR v_end_day NOT BETWEEN 1 AND 31 THEN

        SELECT
            'N' AS status,
            'Invalid or missing payroll cycle settings in company_settings.'
                AS message;

        LEAVE main_block;

    END IF;

    /* 5. Calculate the payroll period */

    SET v_month_start = STR_TO_DATE(
        CONCAT(p_year, '-', LPAD(p_month, 2, '0'), '-01'),
        '%Y-%m-%d'
    );

    SET v_previous_month =
        DATE_SUB(v_month_start, INTERVAL 1 MONTH);

    IF v_start_day > v_end_day THEN

        /* Cross-month cycle: for example, 25th to 24th */

        SET v_start_date = DATE_ADD(
            v_previous_month,
            INTERVAL (
                LEAST(
                    v_start_day,
                    DAY(LAST_DAY(v_previous_month))
                ) - 1
            ) DAY
        );

        SET v_end_date = DATE_ADD(
            v_month_start,
            INTERVAL (
                LEAST(
                    v_end_day,
                    DAY(LAST_DAY(v_month_start))
                ) - 1
            ) DAY
        );

    ELSE

        /* Same-month cycle */

        SET v_start_date = DATE_ADD(
            v_month_start,
            INTERVAL (
                LEAST(
                    v_start_day,
                    DAY(LAST_DAY(v_month_start))
                ) - 1
            ) DAY
        );

        SET v_end_date = DATE_ADD(
            v_month_start,
            INTERVAL (
                LEAST(
                    v_end_day,
                    DAY(LAST_DAY(v_month_start))
                ) - 1
            ) DAY
        );

    END IF;

    IF v_start_date > v_end_date THEN

        SELECT
            'N' AS status,
            'Calculated payroll start date is after the end date.'
                AS message;

        LEAVE main_block;

    END IF;

    SET v_total_days =
        DATEDIFF(v_end_date, v_start_date) + 1;

    /* 6. Prevent regeneration of finalized payroll attendance */

    SELECT COUNT(*)
    INTO v_finalized_count
    FROM payroll_attendance_summary
    WHERE payroll_month = p_month
      AND payroll_year = p_year
      AND is_finalized = 'Y';

    IF v_finalized_count > 0 THEN

        SELECT
            'N' AS status,
            'Attendance is already finalized for this month and cannot be regenerated.'
                AS message;

        LEAVE main_block;

    END IF;

    /* 7. Start transaction */

    START TRANSACTION;

    /*
      Remove only unfinalized summaries.
      Finalized summaries are never deleted by this procedure.
    */

    DELETE FROM payroll_attendance_summary
    WHERE payroll_month = p_month
      AND payroll_year = p_year
      AND (
          is_finalized = 'N'
          OR is_finalized IS NULL
      );

    /* Reset cursor state before opening it */

    SET done = FALSE;
    SET v_generated_count = 0;

    OPEN emp_cursor;

    read_loop: LOOP

        FETCH emp_cursor INTO v_emp_id;

        IF done THEN
            LEAVE read_loop;
        END IF;

        /* 8. Reset employee-specific values */

        SET v_present = 0;
        SET v_wfh = 0;
        SET v_leave = 0;
        SET v_holiday = 0;
        SET v_weekoff = 0;
        SET v_absent = 0;

        SET v_late = 0;
        SET v_half_days = 0;
        SET v_overtime = 0;

        SET v_paid = 0;
        SET v_unpaid = 0;

        /* 9. Calculate attendance counts */

        SELECT
            /* Present includes LATE attendance */

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status))
                         IN ('PRESENT', 'LATE')
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status)) = 'WFH'
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status))
                         IN ('LEAVE', 'PL', 'SL', 'CL', 'ML')
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status)) = 'HOLIDAY'
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status))
                         IN ('WEEKOFF', 'WEEKLY_OFF')
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status))
                         IN ('ABSENT', 'A', 'LOP')
                    THEN 1
                    ELSE 0
                END
            ), 0),

            COALESCE(SUM(
                CASE
                    WHEN UPPER(TRIM(status)) = 'LATE'
                    THEN 1
                    ELSE 0
                END
            ), 0)

        INTO
            v_present,
            v_wfh,
            v_leave,
            v_holiday,
            v_weekoff,
            v_absent,
            v_late

        FROM attendance
        WHERE emp_id = v_emp_id
          AND attendance_date BETWEEN v_start_date AND v_end_date;

        /* 10. Calculate working days */

        SET v_working_days = GREATEST(
            v_total_days - v_holiday - v_weekoff,
            0
        );

        /*
          Assumption:
          - PRESENT, WFH and LEAVE count as paid.
          - HOLIDAY and WEEKOFF count as paid days.
          - ABSENT, A and LOP count as unpaid.
          - Leave types are not split into paid and unpaid here.
        */

        SET v_paid =
            v_present
            + v_wfh
            + v_leave
            + v_holiday
            + v_weekoff;

        SET v_unpaid = v_absent;

        /*
          Half days and overtime remain zero because the supplied
          procedure does not define their calculation rules.
        */

        SET v_half_days = 0;
        SET v_overtime = 0;

        /* 11. Insert one summary for this employee */

            emp_id,
            payroll_month,
            payroll_year,
            total_days,
            working_days,
            present_days,
            wfh_days,
            leave_days,
            holiday_days,
            weekly_off_days,
            absent_days,
            paid_days,
            unpaid_days,
            late_count,
            half_days,
            overtime_hours,
            is_finalized,
            created_at,
    updated_at
        )
        VALUES (
            v_emp_id,
            p_month,
            p_year,
            v_total_days,
            v_working_days,
            v_present,
            v_wfh,
            v_leave,
            v_holiday,
            v_weekoff,
            v_absent,
            v_paid,
            v_unpaid,
            v_late,
            v_half_days,
            v_overtime,
            'N',
            CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
        );

        SET v_generated_count = v_generated_count + 1;

    END LOOP;

    CLOSE emp_cursor;

    /* 12. Ensure that summaries were generated */

    IF v_generated_count = 0 THEN

        ROLLBACK;

        SELECT
            'N' AS status,
            'No active employees found. No payroll attendance summaries were generated.'
                AS message;

        LEAVE main_block;

    END IF;

    /* 13. Commit */

    COMMIT;

    SELECT
        'Y' AS status,
        CONCAT(
            'Payroll attendance generated successfully for period ',
            DATE_FORMAT(v_start_date, '%d-%b-%Y'),
            ' to ',
            DATE_FORMAT(v_end_date, '%d-%b-%Y'),
            '. Employees processed: ',
            v_generated_count,
            '. Status: NOT FINALIZED.'
        ) AS message,
        v_start_date AS period_start,
        v_end_date AS period_end,
        v_generated_count AS generated_employee_count;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_get_company_settings` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `sp_get_company_settings`()
BEGIN
    SELECT * FROM `company_settings` ORDER BY `id` ASC LIMIT 1;
END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_get_payroll_cycle_status` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `sp_get_payroll_cycle_status`(
    IN p_financial_year VARCHAR(9)
)
BEGIN
    DECLARE v_start_year INT;
    DECLARE v_end_year INT;
    DECLARE v_cycle_start_day INT;
    DECLARE v_cycle_end_day INT;
    DECLARE v_total_records INT DEFAULT 0;

    -- Set timezone to India Standard Time
    SET time_zone = '+05:30';

    -- Validate financial year format
    IF p_financial_year IS NULL
       OR p_financial_year NOT REGEXP '^[0-9]{4}-[0-9]{4}$'
    THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Invalid financial year. Use YYYY-YYYY.';
    END IF;

    SET v_start_year =
        CAST(LEFT(p_financial_year, 4) AS UNSIGNED);

    SET v_end_year =
        CAST(RIGHT(p_financial_year, 4) AS UNSIGNED);

    -- Validate consecutive years
    IF v_end_year <> v_start_year + 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Financial year must contain consecutive years.';
    END IF;

    -- Get company payroll cycle settings
    SELECT
        payroll_cycle_start_day,
        payroll_cycle_end_day
    INTO
        v_cycle_start_day,
        v_cycle_end_day
    FROM company_settings
    ORDER BY id
    LIMIT 1;

    IF v_cycle_start_day IS NULL
       OR v_cycle_end_day IS NULL
       OR v_cycle_start_day NOT BETWEEN 1 AND 31
       OR v_cycle_end_day NOT BETWEEN 1 AND 31
    THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Invalid payroll cycle configuration.';
    END IF;

    -- Check payroll attendance data for the financial year
    SELECT COUNT(*)
    INTO v_total_records
    FROM payroll_attendance_summary
    WHERE
        (payroll_year = v_start_year
         AND payroll_month BETWEEN 4 AND 12)
        OR
        (payroll_year = v_end_year
         AND payroll_month BETWEEN 1 AND 3);

    -- If no payroll data exists for the entire financial year
    IF v_total_records = 0 THEN

        SELECT
            p_financial_year AS financial_year,
            NULL AS payroll_year,
            NULL AS payroll_month,
            NULL AS cycle_name,
            NULL AS cycle_start_date,
            NULL AS cycle_end_date,
            0 AS employee_count,
            0 AS finalized_employee_count,
            'N' AS status,
            NULL AS attendance_status,
            'Data not available' AS remarks,
            '+05:30' AS timezone;

    ELSE

        WITH RECURSIVE payroll_months AS (
            -- Start from April
            SELECT
                1 AS month_no,
                v_start_year AS payroll_year,
                4 AS payroll_month

            UNION ALL

            SELECT
                month_no + 1,
                CASE
                    WHEN payroll_month = 12
                        THEN payroll_year + 1
                    ELSE payroll_year
                END,
                CASE
                    WHEN payroll_month = 12
                        THEN 1
                    ELSE payroll_month + 1
                END
            FROM payroll_months
            WHERE month_no < 12
        ),

        cycle_dates AS (
            SELECT
                pm.month_no,
                pm.payroll_month,
                pm.payroll_year,
                STR_TO_DATE(
                    CONCAT(
                        pm.payroll_year, '-',
                        LPAD(pm.payroll_month, 2, '0'),
                        '-01'
                    ),
                    '%Y-%m-%d'
                ) AS month_first_day
            FROM payroll_months pm
        ),

        calculated_cycles AS (
            SELECT
                month_no,
                payroll_month,
                payroll_year,

                DATE_FORMAT(
                    month_first_day,
                    '%M %Y'
                ) AS cycle_name,

                -- Cycle start date
                CASE
                    WHEN v_cycle_start_day > v_cycle_end_day
                    THEN DATE_ADD(
                        DATE_SUB(
                            DATE_SUB(
                                month_first_day,
                                INTERVAL 1 DAY
                            ),
                            INTERVAL DAYOFMONTH(
                                DATE_SUB(
                                    month_first_day,
                                    INTERVAL 1 DAY
                                )
                            ) - 1 DAY
                        ),
                        INTERVAL LEAST(
                            v_cycle_start_day,
                            DAY(
                                LAST_DAY(
                                    DATE_SUB(
                                        month_first_day,
                                        INTERVAL 1 MONTH
                                    )
                                )
                            )
                        ) - 1 DAY
                    )
                    ELSE DATE_ADD(
                        month_first_day,
                        INTERVAL LEAST(
                            v_cycle_start_day,
                            DAY(LAST_DAY(month_first_day))
                        ) - 1 DAY
                    )
                END AS cycle_start_date,

                -- Cycle end date
                DATE_ADD(
                    month_first_day,
                    INTERVAL LEAST(
                        v_cycle_end_day,
                        DAY(LAST_DAY(month_first_day))
                    ) - 1 DAY
                ) AS cycle_end_date

            FROM cycle_dates
        ),

        monthly_summary AS (
            SELECT
                payroll_year,
                payroll_month,
                COUNT(summary_id) AS employee_count,

                SUM(
                    CASE
                        WHEN is_finalized = 'Y' THEN 1
                        ELSE 0
                    END
                ) AS finalized_employee_count

            FROM payroll_attendance_summary

            GROUP BY
                payroll_year,
                payroll_month
        )

        SELECT
            p_financial_year AS financial_year,
            cc.payroll_year,
            cc.payroll_month,
            cc.cycle_name,
            cc.cycle_start_date,
            cc.cycle_end_date,

            ms.employee_count,
            ms.finalized_employee_count,

            -- Data availability status
            'Y' AS status,

            -- Monthly attendance finalization status
            CASE
                WHEN ms.finalized_employee_count =
                     ms.employee_count
                THEN 'FINALIZED'
                ELSE 'INPROGRESS'
            END AS attendance_status,

            -- Remarks
            CASE
                WHEN ms.finalized_employee_count =
                     ms.employee_count
                THEN 'All employee payroll summaries are finalized'
                ELSE CONCAT(
                    ms.employee_count -
                    ms.finalized_employee_count,
                    ' employee(s) pending finalization'
                )
            END AS remarks,

            '+05:30' AS timezone

        FROM calculated_cycles cc

        INNER JOIN monthly_summary ms
            ON ms.payroll_month = cc.payroll_month
           AND ms.payroll_year = cc.payroll_year

        ORDER BY cc.month_no DESC;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_get_payroll_finalization_status` */;
ALTER DATABASE `hrmstest` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `sp_get_payroll_finalization_status`(
    IN p_month INT,
    IN p_year INT
)
BEGIN

    IF p_month IS NULL OR p_month NOT BETWEEN 1 AND 12
       OR p_year IS NULL THEN

        SELECT
            'N' AS attendance_status,
            'Invalid month or year' AS message;

    ELSE

        SELECT
            CASE
                WHEN COUNT(*) = 0 THEN 'N'
                WHEN SUM(is_finalized = 'N') > 0 THEN 'N'
                WHEN SUM(is_finalized = 'Y') = COUNT(*) THEN 'Y'
                ELSE 'N'
            END AS attendance_status,

            CASE
                WHEN COUNT(*) = 0
                    THEN 'Data not available'
                WHEN SUM(is_finalized = 'Y') = COUNT(*)
                    THEN 'Attendance finalized'
                ELSE 'Attendance not finalized'
            END AS message

        FROM payroll_attendance_summary
        WHERE payroll_month = p_month
          AND payroll_year = p_year;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `hrmstest` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci ;
