        effective_from,
        effective_to,
        is_active
    )
    SELECT
        c.component_id,
        'GROSS',
        0.00,
        15000.00,
        'FIXED',
        0.00,
        'NONE',
        1,
        '2026-01-01',
        NULL,
        1
    FROM test_table_salary_component_master c
    WHERE c.component_code = 'PT'
      AND NOT EXISTS
      (
          SELECT 1
          FROM test_table_salary_component_slab s
          WHERE s.component_id = c.component_id
            AND s.slab_min_value = 0.00
            AND s.slab_max_value = 15000.00
            AND s.effective_from = '2026-01-01'
      );


        component_id,
        slab_based_on,
        slab_min_value,
        slab_max_value,
        result_type,
        result_value,
        percentage_base,
        priority,
        effective_from,
        effective_to,
        is_active
    )
    SELECT
        c.component_id,
        'GROSS',
        15000.01,
        20000.00,
        'FIXED',
        150.00,
        'NONE',
        2,
        '2026-01-01',
        NULL,
        1
    FROM test_table_salary_component_master c
    WHERE c.component_code = 'PT'
      AND NOT EXISTS
      (
          SELECT 1
          FROM test_table_salary_component_slab s
          WHERE s.component_id = c.component_id
            AND s.slab_min_value = 15000.01
            AND s.slab_max_value = 20000.00
            AND s.effective_from = '2026-01-01'
      );


        component_id,
        slab_based_on,
        slab_min_value,
        slab_max_value,
        result_type,
        result_value,
        percentage_base,
        priority,
        effective_from,
        effective_to,
        is_active
    )
    SELECT
        c.component_id,
        'GROSS',
        20000.01,
        NULL,
        'FIXED',
        200.00,
        'NONE',
        3,
        '2026-01-01',
        NULL,
        1
    FROM test_table_salary_component_master c
    WHERE c.component_code = 'PT'
      AND NOT EXISTS
      (
          SELECT 1
          FROM test_table_salary_component_slab s
          WHERE s.component_id = c.component_id
            AND s.slab_min_value = 20000.01
            AND s.slab_max_value IS NULL
            AND s.effective_from = '2026-01-01'
      );


    /* ============================================================
       3. VERIFICATION
       ============================================================ */

    SELECT
        component_id,
        component_code,
        component_name,
        component_type,
        calculation_type,
        percentage_base,
        percentage_value,
        formula_expression,
        calculation_order,
        is_active
    FROM test_table_salary_component_master
    ORDER BY calculation_order, component_id;


    SELECT
        s.slab_id,
        c.component_code,
        c.component_name,
        s.slab_based_on,
        s.slab_min_value,
        s.slab_max_value,
        s.result_type,
        s.result_value,
        s.percentage_base,
        s.priority,
        s.effective_from,
        s.effective_to,
        s.is_active
    FROM test_table_salary_component_slab s
    INNER JOIN test_table_salary_component_master c
        ON c.component_id = s.component_id
    ORDER BY
        c.calculation_order,
        s.priority,
        s.slab_min_value;

END
;;
DELIMITER ;
