CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `store_forgot_password_token`(
    IN p_emp_id VARCHAR(20),
    IN p_reset_token VARCHAR(255)
)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- check employee exists or not
    SELECT COUNT(*) INTO v_count
    FROM user_login_details
    WHERE emp_id = p_emp_id;

    IF v_count > 0 THEN

        -- deactivate old tokens
        UPDATE forgot_password_tokens
        SET active = 'N'
        WHERE emp_id = p_emp_id
          AND active = 'Y';

        -- insert new token
            emp_id,
            reset_token,
            active,
            created_on
        )
        VALUES (
            p_emp_id,
            p_reset_token,
            'Y',
            NOW()
        );

        -- success response
        SELECT
            'Y' AS status,
            p_emp_id AS emp_id,
            p_reset_token AS reset_token,
            'token stored successfully' AS remarks;

    ELSE

        -- employee not found
        SELECT
            'N' AS status,
            p_emp_id AS emp_id,
            NULL AS reset_token,
            'employee not found' AS remarks;

    END IF;

END
;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
