CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `submit_candidate_details`(

    IN p_ref_id VARCHAR(20)

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- validate candidate

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE ref_id = p_ref_id;

    IF v_count > 0 THEN

        -- final submit

        UPDATE candidate_details
        SET
            is_submitted = 1,
            onboarding_status = 'SUBMITTED'
        WHERE ref_id = p_ref_id;

        -- success response

        SELECT
            'Y' AS status,
            p_ref_id AS ref_id,
            'details submitted successfully' AS remarks;

    ELSE

        SELECT
            'N' AS status,
            p_ref_id AS ref_id,
            'candidate not found' AS remarks;

    END IF;

END
;;
