/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `test_add_salary_component_slab`(
    IN p_emp_id VARCHAR(20),
    IN p_component_id BIGINT,
    IN p_slab_json JSON
)
BEGIN

    DECLARE v_role VARCHAR(30);
    DECLARE v_component_exists INT DEFAULT 0;
    DECLARE v_slab_count INT DEFAULT 0;
    DECLARE v_inserted_count INT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;

        SELECT
            'N' AS status,
            'Error occurred while adding salary slabs' AS remarks;
    END;

    SET time_zone = '+05:30';

    START TRANSACTION;


    /* =========================================================
       1. CHECK USER
       ========================================================= */

    SELECT user_category
    INTO v_role
    FROM user_login_details
    WHERE emp_id = p_emp_id
      AND status = 'Y'
    LIMIT 1;


    IF v_role IS NULL THEN

        ROLLBACK;

        SELECT
            'N' AS status,
            'Invalid or inactive user' AS remarks;


    ELSEIF v_role NOT IN ('ADMIN', 'HR', 'SUPERADMIN') THEN

        ROLLBACK;

        SELECT
            'N' AS status,
            'Only ADMIN, HR or SUPERADMIN can add salary slabs'
            AS remarks;


    ELSE


        /* =====================================================
           2. CHECK COMPONENT
           ===================================================== */

        SELECT COUNT(*)
        INTO v_component_exists
        FROM test_table_salary_component_master
        WHERE component_id = p_component_id
          AND is_active = 1;


        IF v_component_exists = 0 THEN

            ROLLBACK;

            SELECT
                'N' AS status,
                CONCAT(
                    'Active salary component not found: ',
                    p_component_id
                ) AS remarks;


        ELSE


            /* =================================================
               3. CHECK JSON
               ================================================= */

            IF p_slab_json IS NULL
               OR JSON_VALID(p_slab_json) = 0
               OR JSON_TYPE(p_slab_json) <> 'ARRAY' THEN

                ROLLBACK;

                SELECT
                    'N' AS status,
                    'Slab data must be a valid JSON array'
                    AS remarks;


            ELSE


                SET v_slab_count =
                    JSON_LENGTH(p_slab_json);


                IF v_slab_count = 0 THEN

                    ROLLBACK;

                    SELECT
                        'N' AS status,
                        'At least one slab is required'
                        AS remarks;


                ELSE


                    /* =========================================
                       4. INSERT ALL SLABS
                       ========================================= */

                        component_id,
                        slab_based_on,
                        slab_min_value,
                        slab_max_value,
                        result_type,
                        result_value,
                        percentage_base,
                        priority,
                        effective_from,
                        effective_to,
                        is_active,
                        created_at,
                        updated_at
                    )
                    SELECT
                        p_component_id,

                        JSON_UNQUOTE(
                            JSON_EXTRACT(
                                jt.slab_data,
                                '$.slab_based_on'
                            )
                        ),

                        CAST(
                            JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.slab_min_value'
                                )
                            ) AS DECIMAL(12,2)
                        ),

                        CASE
                            WHEN JSON_EXTRACT(
                                jt.slab_data,
                                '$.slab_max_value'
                            ) IS NULL
                            OR JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.slab_max_value'
                                )
                            ) = 'null'
                            THEN NULL
                            ELSE CAST(
                                JSON_UNQUOTE(
                                    JSON_EXTRACT(
                                        jt.slab_data,
                                        '$.slab_max_value'
                                    )
                                ) AS DECIMAL(12,2)
                            )
                        END,

                        JSON_UNQUOTE(
                            JSON_EXTRACT(
                                jt.slab_data,
                                '$.result_type'
                            )
                        ),

                        CAST(
                            JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.result_value'
                                )
                            ) AS DECIMAL(12,2)
                        ),

                        JSON_UNQUOTE(
                            JSON_EXTRACT(
                                jt.slab_data,
                                '$.percentage_base'
                            )
                        ),

                        CAST(
                            JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.priority'
                                )
                            ) AS SIGNED
                        ),

                        CAST(
                            JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.effective_from'
                                )
                            ) AS DATE
                        ),

                        CASE
                            WHEN JSON_EXTRACT(
                                jt.slab_data,
                                '$.effective_to'
                            ) IS NULL
                            OR JSON_UNQUOTE(
                                JSON_EXTRACT(
                                    jt.slab_data,
                                    '$.effective_to'
                                )
                            ) = 'null'
                            THEN NULL
                            ELSE CAST(
                                JSON_UNQUOTE(
                                    JSON_EXTRACT(
                                        jt.slab_data,
                                        '$.effective_to'
                                    )
                                ) AS DATE
                            )
                        END,

                        1,
                        NOW(),
                        NOW()

                    FROM JSON_TABLE(
                        p_slab_json,
                        '$[*]'
                        COLUMNS
                        (
                            slab_data JSON PATH '$'
                        )
                    ) jt;


                    SET v_inserted_count = ROW_COUNT();


                    /* =========================================
                       5. COMMIT
                       ========================================= */

                    COMMIT;


                    /* =========================================
                       6. SUCCESS
                       ========================================= */

                    SELECT
                        'Y' AS status,
                        CONCAT(
                            v_inserted_count,
                            ' salary slab(s) added successfully'
                        ) AS remarks,
                        p_component_id AS component_id,
                        v_inserted_count AS inserted_count;

                END IF;

            END IF;

        END IF;

    END IF;

END
;;
DELIMITER ;
