CREATE DEFINER=`hrmstest`@`183.82.99.183` PROCEDURE `validate_candidate_login`(

    IN p_ref_id VARCHAR(20),
    IN p_password VARCHAR(50)

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    -- validate login

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE ref_id = p_ref_id
    AND temp_password = p_password;

    IF v_count > 0 THEN

        SELECT
            'Y' AS status,
            ref_id,
            emp_name,
            email,
            onboarding_status,
            current_step,
            'login success' AS remarks
        FROM candidate_details
        WHERE ref_id = p_ref_id;

    ELSE

        SELECT
            'N' AS status,
            NULL AS ref_id,
            NULL AS emp_name,
            'invalid credentials' AS remarks;

    END IF;

END
;;
